def new_id():
    return uuid.uuid4().hex[:10]


def normalize_service(raw):
    """把舊版或手改過的服務設定整理成完整欄位。"""
    if not isinstance(raw, dict):
        return None
    role = str(raw.get("role") or DEFAULT_ROLE)
    return {
        "id": str(raw.get("id") or new_id()),
        "name": str(raw.get("name") or ""),
        "role": role if role in ROLES else DEFAULT_ROLE,
        "url": str(raw.get("url") or ""),
        "model": str(raw.get("model") or ""),
        "credential_env": str(raw.get("credential_env") or ""),
        "enabled": bool(raw.get("enabled", True)),
        "temperature": str(raw.get("temperature") or ""),
        "max_tokens": str(raw.get("max_tokens") or ""),
        "task": str(raw.get("task") or ""),
        "num_ctx": str(raw.get("num_ctx") or "") if str(raw.get("num_ctx") or "").isdigit() else "",   # 本機（Ollama）上下文長度
        "keep_alive": str(raw.get("keep_alive") or ""),                                                 # 本機模型用完保持載入多久
        "reasoning": str(raw.get("reasoning") or "") if str(raw.get("reasoning") or "") in REASONING_LEVELS else "",          # 自訂工作說明（給這位 AI 的具體分工）
    }


MODEL_LIKE_NAME = re.compile(r"^(?=[a-z0-9._:\-]+$)(?=.*-)(?=.*(\d+(\.\d+)?b\b|-v\d|\d+\.\d+|:)).*$")   # 像模型名稱：有連字號與版本／大小


def fix_service_names(services):
    """名稱跟著模型：空白、「AI 3」或看起來是別的模型名稱（例如換了模型卻還叫舊模型名）時，改成目前模型的簡稱；
    同名的加上（2）（3）區分。使用者自己取的名字（例如「DeepSeek」「研究員」）不會動。回傳是否有改動。"""
    changed = False
    seen = {}
    for sv in services:
        model_short = (sv.get("model") or "").rstrip("/").split("/")[-1]
        name = (sv.get("name") or "").strip()
        base = re.sub(r"（\d+）$", "", name)
        if model_short and (not name or re.fullmatch(r"AI\s*\d+", name)
                            or (MODEL_LIKE_NAME.match(base) and base != model_short)):
            base = model_short
        count = seen.get(base, 0) + 1
        seen[base] = count
        new = base if count == 1 else f"{base}（{count}）"
        if new != name:
            sv["name"] = new
            changed = True
    return changed


def default_settings():
    url = f"https://{NVIDIA_HOST}/v1"
    services = [
        normalize_service({"name": "GLM", "role": "程式專家", "url": url, "model": "z-ai/glm-5.3-flash",
                           "credential_env": DEFAULT_NVIDIA_ENV}),
        normalize_service({"name": "DeepSeek", "role": "研究分析", "url": url, "model": "deepseek-ai/deepseek-v4.1-flash",
                           "credential_env": DEFAULT_NVIDIA_ENV}),
    ]
    prefs = dict(DEFAULT_PREFERENCES, hub_id=services[0]["id"])
    return {"version": SETTINGS_VERSION, "services": services, "removed_services": [],
            "templates": {}, "deleted_templates": {}, "preferences": prefs, "schedules": [], "removed_schedules": []}


def find_importable_settings():
    """打包的 exe 放在 dist/ 執行時，設定會存在 dist/ 自己這裡（與 AI協作.py 旁邊的不同）。
    第一次啟動、這裡還沒有設定檔時，找上一層（通常是程式資料夾）有沒有可以沿用的設定，回傳路徑或空字串。"""
    if os.path.exists(SETTINGS_PATH):
        return ""
    for up in (os.path.dirname(APP_DIR), os.path.dirname(os.path.dirname(APP_DIR))):
        cand = os.path.join(up, os.path.basename(SETTINGS_PATH))
        if os.path.normcase(cand) != os.path.normcase(SETTINGS_PATH) and os.path.isfile(cand):
            return cand
    return ""


def import_settings_from(src):
    """把別處的設定複製到這個資料夾（不覆蓋已存在的）。回傳是否成功。"""
    if os.path.exists(SETTINGS_PATH) or not os.path.isfile(src):
        return False
    try:
        with open(src, "r", encoding="utf-8") as f:
            data = json.load(f)
        save_settings_file(data)
        return True
    except (OSError, ValueError):
        return False


def load_settings_file(path=SETTINGS_PATH):
    """回傳 (設定 dict, 警告訊息或空字串)。讀不到時回傳預設值；壞掉的檔案會先備份再用預設值。"""
    if not os.path.exists(path):
        return default_settings(), ""
    try:
        with open(path, "r", encoding="utf-8") as source:
            data = json.load(source)
        if not isinstance(data, dict):
            raise TypeError("設定檔格式不是物件")
    except (OSError, ValueError, TypeError) as exc:
        saved = backup_file(path, reason="無法讀取")
        log.exception("讀取設定失敗")
        return default_settings(), f"讀取服務設定失敗，已改用預設值。\n原檔已備份到：{saved}\n{exc}"

    settings = default_settings()
    services = [s for s in (normalize_service(x) for x in data.get("services", []) or []) if s]
    if services or "services" in data:
        settings["services"] = services
    settings["removed_services"] = [s for s in (normalize_service(x) for x in data.get("removed_services", []) or []) if s]
    for item, raw in zip(settings["removed_services"], data.get("removed_services", []) or []):
        if isinstance(raw, dict):
            item["removed_at"] = str(raw.get("removed_at", ""))
    templates = data.get("templates", {})
    if isinstance(templates, dict):
        settings["templates"] = {str(k): str(v) for k, v in templates.items()}
    deleted = data.get("deleted_templates", {})
    if isinstance(deleted, dict):
        settings["deleted_templates"] = {str(k): v for k, v in deleted.items() if isinstance(v, dict)}
    for key in ("schedules", "removed_schedules"):
        settings[key] = [dict(x) for x in (data.get(key) or []) if isinstance(x, dict) and x.get("id")]
    prefs = dict(DEFAULT_PREFERENCES)
    if isinstance(data.get("preferences"), dict):
        prefs.update({k: v for k, v in data["preferences"].items() if k in DEFAULT_PREFERENCES})
    if prefs["mode"] not in MODES:
        prefs["mode"] = DEFAULT_PREFERENCES["mode"]
    if not any(s["id"] == prefs.get("hub_id") for s in settings["services"]):
        prefs["hub_id"] = settings["services"][0]["id"] if settings["services"] else ""
    if prefs.get("agent_model_id") and not any(s["id"] == prefs["agent_model_id"] for s in settings["services"]):
        prefs["agent_model_id"] = settings["services"][0]["id"] if settings["services"] else ""      # 指到已移除的 AI 時改用第一位
    settings["preferences"] = prefs
    return settings, ""


def backup_file(path, reason=""):
    """把檔案複製到「備份/設定/」，檔名加上時間。回傳備份路徑（失敗回傳空字串）。"""
    if not os.path.exists(path):
        return ""
    os.makedirs(SETTINGS_BACKUP_DIR, exist_ok=True)
    base, ext = os.path.splitext(os.path.basename(path))
    stamp = time.strftime("%Y%m%d_%H%M%S")
    suffix = f"_{reason}" if reason else ""
    target = os.path.join(SETTINGS_BACKUP_DIR, f"{base}_{stamp}{suffix}{ext}")
    counter = 1
    while os.path.exists(target):
        target = os.path.join(SETTINGS_BACKUP_DIR, f"{base}_{stamp}{suffix}_{counter}{ext}")
        counter += 1
    try:
        shutil.copy2(path, target)
        return target
    except OSError:
        log.exception("備份設定檔失敗")
        return ""


def settings_file_digest(path=SETTINGS_PATH):
    try:
        with open(path, "rb") as f:
            return hashlib.sha256(f.read()).hexdigest()
    except OSError:
        return ""


SCHEDULE_RUN_FIELDS = ("last_run", "last_status", "next")


def merge_external_settings(ours, disk):
    """另一個程式（例如 Windows 排程啟動的那個）在這段時間改過設定檔時合併，避免互相覆蓋：
    模型與偏好以目前這個視窗為準；排程的執行狀態取較新的那一份；對方新增的排程保留。
    直接修改 ours 裡的排程（畫面與執行中的排程拿的是同一份），回傳說明清單。"""
    notes = []
    disk_sch = {s.get("id"): s for s in disk.get("schedules") or [] if isinstance(s, dict) and s.get("id")}
    for s in ours.setdefault("schedules", []):
        d = disk_sch.pop(s.get("id"), None)
        if d and (d.get("last_run") or "") > (s.get("last_run") or ""):
            for k in SCHEDULE_RUN_FIELDS:
                s[k] = d.get(k)
            if s.get("repeat") == "once" and d.get("enabled") is False:
                s["enabled"] = False
            notes.append(f"排程「{s.get('name')}」的執行紀錄用另一個視窗較新的版本")
    removed = ours.setdefault("removed_schedules", [])
    removed_ids = {r.get("id") for r in removed if isinstance(r, dict)}
    for d in disk_sch.values():
        if d.get("id") not in removed_ids:
            ours["schedules"].append(d)
            notes.append(f"保留另一個視窗新增的排程「{d.get('name')}」")
    for r in disk.get("removed_schedules") or []:
        if isinstance(r, dict) and r.get("id") not in removed_ids:
            removed.append(r)
            removed_ids.add(r.get("id"))
            ours["schedules"] = [s for s in ours["schedules"] if s.get("id") != r.get("id")]
    return notes


class InstanceLock:
    """同一個程式資料夾只讓一個程式「負責」排程與設定。用作業系統的檔案鎖：程式結束（含當機）時自動釋放。"""

    def __init__(self, path=None):
        self.path = path or os.path.join(LOG_DIR, "執行中.lock")
        self.f = None

    def acquire(self):
        try:
            os.makedirs(os.path.dirname(self.path), exist_ok=True)
            f = open(self.path, "a+b")
        except OSError:
            return True                      # 建不了鎖檔就不要擋住使用者
        try:
            f.seek(0)
            if os.name == "nt":
                import msvcrt
                msvcrt.locking(f.fileno(), msvcrt.LK_NBLCK, 1)
            else:
                import fcntl
                fcntl.flock(f.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
        except OSError:
            f.close()
            return False
        self.f = f
        return True

    def release(self):
        if not self.f:
            return
        try:
            self.f.seek(0)
            if os.name == "nt":
                import msvcrt
                msvcrt.locking(self.f.fileno(), msvcrt.LK_UNLCK, 1)
            else:
                import fcntl
                fcntl.flock(self.f.fileno(), fcntl.LOCK_UN)
        except OSError:
            pass
        try:
            self.f.close()
        except OSError:
            pass
        self.f = None


def save_settings_file(settings, path=SETTINGS_PATH):
    """寫入設定（先寫暫存檔再取代）。內容有變時先備份舊檔。失敗時丟出 OSError。"""
    data = dict(settings, version=SETTINGS_VERSION)
    text = json.dumps(data, ensure_ascii=False, indent=2)
    if os.path.exists(path):
        try:
            with open(path, "r", encoding="utf-8") as source:
                old = source.read()
        except OSError:
            old = None
        if old == text:
            return ""
        backup_file(path)
    tmp_path = path + ".tmp"
    with open(tmp_path, "w", encoding="utf-8") as output:
        output.write(text)
    safe_replace(tmp_path, path)
    return path


# ───────────────────────── 執行紀錄 ─────────────────────────
STATUS_LABELS = {"interrupted": "中斷（程式沒有正常結束，以下是已完成的部分）", "done": "完成", "partial": "完成（部分失敗）", "stopped": "已停止", "error": "失敗", "timeout": "逾時", "empty": "沒有內容",
                 "running": "執行中"}


def result_summary(result):
    if not result:
        return "未執行"
    label = STATUS_LABELS.get(result.get("status"), result.get("status", ""))
    if result.get("label") and result.get("status") not in ("done",):
        label += f"（{result['label']}）"
    parts = [label, f"耗時 {result.get('elapsed', 0):.1f} 秒"]
    if result.get("ttft") is not None:
        parts.append(f"首字 {result['ttft']:.1f} 秒")
    usage = result.get("usage") or {}
    if usage.get("completion_tokens"):
        parts.append(f"輸出 {usage['completion_tokens']} tokens")
    return "｜".join(parts)


def record_to_markdown(record):
    names = {a["id"]: f"{a['name']}（{a.get('role') or ''}｜{a.get('model') or ''}）" for a in record.get("agents", [])}
    hub = record.get("hub")
    if hub:
        names["__hub__"] = f"主持 AI：{hub.get('name')}（{hub.get('model')}）"
    lines = [f"# 多 AI 協作紀錄 — {record.get('started_at', '')}", "",
             f"- 模式：{record.get('mode')}",
             f"- 狀態：{STATUS_LABELS.get(record.get('status'), record.get('status'))}",
             f"- 結束時間：{record.get('finished_at', '')}",
             "- 參與 AI：" + "、".join(names.get(a["id"], a["name"]) for a in record.get("agents", [])), ""]
    if hub and record.get("mode") not in (MODE_PARALLEL, MODE_RELAY):
        lines.insert(-1, f"- 主持 AI：{hub.get('name')}（{hub.get('model')}）")
    header_end = len(lines) - 1
    if record.get("system_prompt"):
        lines += ["## 系統提示詞", "", record["system_prompt"], ""]
    lines += ["## 提示詞", "", record.get("prompt", ""), ""]
    usage = record.get("usage_total") or {}
    if usage:
        tok = usage.get("prompt", 0) + usage.get("completion", 0)
        line = f"- 用量：{usage.get('calls', 0)} 次呼叫、{tok:,} tokens"
        if usage.get("estimated"):
            line += f"（另有約 {usage['estimated']:,} 估算值，服務未回報用量）"
        lines.insert(header_end, line + (f"、總耗時 {record.get('elapsed', 0):.0f} 秒" if record.get("elapsed") else ""))
        header_end += 1
    if record.get("seed_round"):
        lines.insert(header_end, f"- 從第 {record['seed_round']} 輪的結果接續")
    if record.get("notes"):
        lines += ["## 使用者補充指示", ""] + [f"- {n}" for n in record["notes"]] + [""]
    final = record.get("final")
    if final and final.get("text"):
        lines += [f"## 最終成果（{final.get('name', '')}）", ""]
        if final.get("note"):
            lines += [f"> {final['note']}", ""]
        if final.get("disagreement"):
            lines += [f"> ⚠ 各 AI 的結論不一致：{final['disagreement']}", ""]
        if final.get("labels"):
            lines += ["> 代號對照：" + "、".join(f"回答 {k}＝{v}" for k, v in final["labels"].items()), ""]
        lines += [final["text"], ""]
    plan = record.get("plan")
    if plan:
        lines += ["## 主持 AI 的分工規劃", "", plan.get("text", ""), ""]
    for rnd in record.get("rounds", []):
        lines += [f"## 第 {rnd['round']} 輪：{rnd['label']}" if "接力" not in rnd["label"] else f"## {rnd['label']}", ""]
        if rnd.get("ranking"):
            ordered = sorted(rnd["ranking"].items(), key=lambda kv: kv[1][0])
            lines += ["**互評綜合名次**：" + " > ".join(f"{names.get(pid, pid)}（平均 {v[0]:.1f}）" for pid, v in ordered), ""]
        for pid, result in rnd.get("answers", {}).items():
            lines += [f"### {names.get(pid, pid)}", "", f"_{result_summary(result)}_", ""]
            if (rnd.get("tasks") or {}).get(pid):
                lines += [f"> 子任務：{rnd['tasks'][pid]}", ""]
            if (rnd.get("anon") or {}).get(pid):
                lines += ["> 本輪看到的匿名代號：" + "、".join(f"{k}＝{names.get(v, v)}" for k, v in rnd["anon"][pid].items()), ""]
            if result.get("text"):
                lines += [result["text"], ""]
            if result.get("error"):
                lines += [f"> 錯誤：{result['error']}", ""]
    hub_result = record.get("hub_result")
    if hub_result:
        lines += ["## 主持 AI 彙整", "", f"_{result_summary(hub_result)}_", ""]
        if hub_result.get("error"):
            lines += [f"> 錯誤：{hub_result['error']}", ""]
    if record.get("error"):
        lines += [f"> 結果：{record['error']}", ""]
    if record.get("timeline"):
        lines += ["## 時間軸", ""]
        for secs, who, text in record["timeline"]:
            lines.append(f"- {secs:>6.1f} 秒｜{names.get(who, who)}｜{text}")
        lines.append("")
    partial = record.get("partial_answers") or {}
    if partial and record.get("status") in ("running", "interrupted"):
        lines += ["", "## 中斷前已完成的回答", ""]
        for item in partial.values():
            lines += [f"### {item.get('name')}（{item.get('note') or ''}）", "", item.get("text") or "（沒有內容）", ""]
    return "\n".join(lines)


UI_STATE_PATH = os.path.join(APP_DIR, "AI協作介面狀態.json")


def load_ui_state():
    """視窗大小、位置、分隔線位置等（獨立小檔，不影響設定檔與其備份）。"""
    try:
        with open(UI_STATE_PATH, "r", encoding="utf-8") as source:
            data = json.load(source)
        return data if isinstance(data, dict) else {}
    except (OSError, ValueError):
        return {}


def save_ui_state(state):
    tmp = UI_STATE_PATH + ".tmp"
    with open(tmp, "w", encoding="utf-8") as output:
        json.dump(state, output, ensure_ascii=False, indent=2)
    safe_replace(tmp, UI_STATE_PATH)


def safe_filename(text):
    return re.sub(r'[<>:"/\\|?*\s]+', "_", text or "").strip("_") or "紀錄"


def new_record_base(mode, folder=RECORDS_DIR):
    """一次討論的紀錄檔名（不含副檔名）。開始時就決定好，中途存檔與最後存檔寫同一個檔，不留多餘檔案。"""
    os.makedirs(folder, exist_ok=True)
    base = os.path.join(folder, f"{time.strftime('%Y%m%d_%H%M%S')}_{safe_filename(mode)}")
    path, counter = base, 1
    while os.path.exists(path + ".md") or os.path.exists(path + ".json"):
        path = f"{base}_{counter}"
        counter += 1
    return path


def _write_text_atomic(path, text):
    tmp = path + ".tmp"
    with open(tmp, "w", encoding="utf-8") as output:
        output.write(text)
    safe_replace(tmp, path)


def save_record(record, folder=RECORDS_DIR, base=None):
    """把一次執行存成 .md 與 .json（先寫暫存檔再取代）。給 base 時寫到那個固定檔名（中途存檔用）。回傳 .md 路徑。"""
    path = base or new_record_base(record.get("mode"), folder)
    _write_text_atomic(path + ".md", record_to_markdown(record))
    _write_text_atomic(path + ".json", json.dumps(record, ensure_ascii=False, indent=2, default=str))
    return path + ".md"


def pid_alive(pid):
    """這個行程還在不在（用來判斷「執行中」的紀錄是不是當機留下的）。"""
    try:
        pid = int(pid)
    except (TypeError, ValueError):
        return False
    if pid <= 0:
        return False
    if os.name == "nt":
        try:
            import ctypes
            k32 = ctypes.windll.kernel32
            handle = k32.OpenProcess(0x1000, False, pid)            # PROCESS_QUERY_LIMITED_INFORMATION
            if not handle:
                return False
            code = ctypes.c_ulong()
            ok = k32.GetExitCodeProcess(handle, ctypes.byref(code))
            k32.CloseHandle(handle)
            return bool(ok) and code.value == 259                    # STILL_ACTIVE
        except Exception:
            return True                                              # 判斷不了就當作還在，不要誤標
    try:
        os.kill(pid, 0)
    except ProcessLookupError:
        return False
    except OSError:
        return True
    try:                                     # 已經結束、只是還沒被回收的殭屍程序（Linux）不算還在
        with open(f"/proc/{pid}/stat", "r") as f:
            return f.read().rsplit(")", 1)[-1].split()[0] != "Z"
    except (OSError, IndexError):
        return True


def find_interrupted_records(folder=RECORDS_DIR, days=14):
    """找出上次沒有正常結束的討論（中途存檔的狀態還是「執行中」、而且那個程式已經不在了），
    把狀態改成「中斷」並更新 .md，回傳 .md 路徑清單。不刪除任何東西。"""
    out = []
    try:
        names = [n for n in os.listdir(folder) if n.endswith(".json")]
    except OSError:
        return out
    limit = time.time() - days * 86400
    for n in names:
        path = os.path.join(folder, n)
        try:
            if os.path.getmtime(path) < limit:
                continue
            with open(path, encoding="utf-8") as f:
                rec = json.load(f)
        except (OSError, ValueError):
            continue
        if not isinstance(rec, dict) or rec.get("status") != "running" or pid_alive(rec.get("pid")):
            continue
        rec["status"] = "interrupted"
        try:
            save_record(rec, base=path[:-5])
            out.append(path[:-5] + ".md")
        except OSError:
            pass
    return out


def keep_awake(on):
    """執行中請 Windows 不要進入睡眠（螢幕仍會照設定關閉）；結束時恢復。必須在同一個執行緒呼叫。"""
    if os.name != "nt":
        return
    try:
        import ctypes
        flags = 0x80000000 | (0x00000001 if on else 0)                 # ES_CONTINUOUS | ES_SYSTEM_REQUIRED
        ctypes.windll.kernel32.SetThreadExecutionState(flags)
    except Exception:
        pass


def list_records(folder=RECORDS_DIR):
    if not os.path.isdir(folder):
        return []
    files = [f for f in os.listdir(folder) if f.lower().endswith(".md")]
    return sorted(files, reverse=True)


# ───────────────────────── 附加檔案 ─────────────────────────
def read_attachment(path, limit=MAX_ATTACH_BYTES):
    """讀取文字檔，回傳 (文字, 警告)。自動嘗試 UTF-8 與 Big5（cp950）。"""
    size = os.path.getsize(path)
    with open(path, "rb") as source:
        raw = source.read(limit)
    warning = f"檔案 {size:,} 位元組，超過上限，只附加前 {limit:,} 位元組。" if size > limit else ""
    if b"\x00" in raw[:4096]:
        raise ValueError("這看起來是二進位檔（例如圖片、Office 檔），只能附加文字檔。")
    for encoding in ("utf-8-sig", "cp950"):
        try:
            return raw.decode(encoding), warning
        except UnicodeDecodeError:
            continue
    return raw.decode("utf-8", errors="replace"), (warning + " 部分字元無法辨識。").strip()


def format_attachment(path, text):
    ext = os.path.splitext(path)[1].lstrip(".").lower()
    lang = {"py": "python", "js": "javascript", "ts": "typescript", "md": "markdown", "ps1": "powershell",
            "cs": "csharp", "sh": "bash", "yml": "yaml"}.get(ext, ext)
    return f"\n【附加檔案：{os.path.basename(path)}】\n```{lang}\n{text.rstrip()}\n```\n"


# ───────────────────────── 日誌 ─────────────────────────
def setup_logging():
    """日誌寫到「日誌/多AI工作台_年月.log」，每月一個檔，不自動刪除。"""
    try:
        os.makedirs(LOG_DIR, exist_ok=True)
        path = os.path.join(LOG_DIR, f"AI協作_{time.strftime('%Y%m')}.log")
        handler = logging.FileHandler(path, encoding="utf-8")
    except OSError:
        handler = logging.StreamHandler()
    handler.setFormatter(logging.Formatter("%(asctime)s %(levelname)s %(name)s：%(message)s"))
    root = logging.getLogger("ai_collab")
    if not root.handlers:
        root.addHandler(handler)
    root.setLevel(logging.INFO)
    return root


# ───────────────────────── 對話（工作階段）存檔 ─────────────────────────
SESSIONS_DIR = os.path.join(APP_DIR, "工作階段")


def new_session(kind, workspace="", model_id=""):
    return {"id": time.strftime("%Y%m%d_%H%M%S_") + uuid.uuid4().hex[:4], "type": kind, "title": "新對話",
            "created": time.strftime("%Y-%m-%d %H:%M:%S"), "updated": time.strftime("%Y-%m-%d %H:%M:%S"),
            "workspace": workspace, "model_id": model_id, "mode": "build", "messages": [], "display": [],
            "changes": [], "todos": [], "council_history": [], "turn": 0, "usage": {}}


def save_session(session):
    os.makedirs(SESSIONS_DIR, exist_ok=True)
    session["updated"] = time.strftime("%Y-%m-%d %H:%M:%S")
    path = os.path.join(SESSIONS_DIR, session["id"] + ".json")
    tmp = path + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(session, f, ensure_ascii=False, indent=1, default=str)
    safe_replace(tmp, path)
    return path


def load_session(session_id):
    with open(os.path.join(SESSIONS_DIR, session_id + ".json"), "r", encoding="utf-8") as f:
        return json.load(f)


def list_sessions():
    """回傳 [(id, 標題, 類型, 更新時間)]，新的在前。封存的不列出。"""
    if not os.path.isdir(SESSIONS_DIR):
        return []
    out = []
    for name in os.listdir(SESSIONS_DIR):
        if not name.endswith(".json"):
            continue
        try:
            with open(os.path.join(SESSIONS_DIR, name), "r", encoding="utf-8") as f:
                data = json.load(f)
            out.append((data["id"], data.get("title") or "未命名", data.get("type", "agent"), data.get("updated", "")))
        except (OSError, ValueError, KeyError):
            continue
    return sorted(out, key=lambda x: x[3], reverse=True)


def archive_session(session_id):
    """封存（移到 工作階段/封存/，不刪除）。"""
    src = os.path.join(SESSIONS_DIR, session_id + ".json")
    dst_dir = os.path.join(SESSIONS_DIR, "封存")
    os.makedirs(dst_dir, exist_ok=True)
    if os.path.exists(src):
        shutil.move(src, os.path.join(dst_dir, session_id + ".json"))


def search_sessions(query, limit=200):
    """在標題與對話內容中搜尋（不分大小寫）。回傳格式同 list_sessions。"""
    q = (query or "").strip().lower()
    if not q:
        return list_sessions()[:limit]
    if not os.path.isdir(SESSIONS_DIR):
        return []
    out = []
    for name in os.listdir(SESSIONS_DIR):
        if not name.endswith(".json"):
            continue
        path = os.path.join(SESSIONS_DIR, name)
        try:
            with open(path, "r", encoding="utf-8") as f:
                raw = f.read()
            data = json.loads(raw)
        except (OSError, ValueError):
            continue
        title = data.get("title") or "未命名"
        if q in title.lower() or q in json.dumps(data.get("display", []), ensure_ascii=False).lower():
            out.append((data.get("id", name[:-5]), title, data.get("type", "agent"), data.get("updated", "")))
    return sorted(out, key=lambda x: x[3], reverse=True)[:limit]


def session_to_markdown(session):
    """把一個對話（Agent 或 AI 討論）轉成 Markdown 文字。"""
    kind = "Agent" if session.get("type") == "agent" else "AI 討論"
    lines = [f"# {session.get('title') or '對話'}", "",
             f"- 類型：{kind}", f"- 建立：{session.get('created', '')}　更新：{session.get('updated', '')}"]
    if session.get("workspace"):
        lines.append(f"- 工作資料夾：`{session['workspace']}`")
    lines.append("")
    for item in session.get("display") or []:
        kind_ = item[0] if item else ""
        if kind_ == "user":
            lines += ["## 你", "", str(item[1]), ""]
        elif kind_ == "assistant":
            who = item[2] if len(item) > 2 else "Agent"
            lines += [f"## {who}", "", str(item[1]), ""]
        elif kind_ == "tool":
            _k, name, title, ok, output = (list(item) + [""] * 5)[:5]
            lines += [f"<details><summary>{'✓' if ok else '✗'} 工具：{title}</summary>", "", "```",
                      str(output).rstrip()[:6000], "```", "", "</details>", ""]
        elif kind_ in ("notice", "error"):
            lines += [f"> {item[1]}", ""]
        elif kind_ == "council":
            rec = item[1] if len(item) > 1 and isinstance(item[1], dict) else {}
            names = {a.get("id"): a.get("name") for a in rec.get("agents") or []}
            lines += [f"## AI 討論（{rec.get('mode', '')}，{len(names)} 位 AI）", ""]
            research = rec.get("research") or {}
            if research.get("sources"):
                lines += ["**上網查到的來源：** " + "、".join(research["sources"]), ""]
            final = (rec.get("final") or {}).get("text")
            if final:
                main, contrib = split_final(final)
                lines += ["### 最終成果", "", main, ""]
                if (rec.get("final") or {}).get("disagreement"):
                    lines += [f"> ⚠ 各 AI 的結論不一致：{rec['final']['disagreement']}", ""]
                if contrib:
                    lines += ["<details><summary>各回答的貢獻與分歧</summary>", "", contrib, "", "</details>", ""]
            for rnd in rec.get("rounds") or []:
                lines += [f"<details><summary>第 {rnd.get('round')} 輪：{rnd.get('label', '')}</summary>", ""]
                for pid, res in (rnd.get("answers") or {}).items():
                    lines += [f"#### {names.get(pid, pid)}", "", str(res.get("text") or res.get("error") or ""), ""]
                lines += ["</details>", ""]
    return "\n".join(lines).rstrip() + "\n"


# ───────────────────────── 排程 ─────────────────────────
REPEATS = {"once": "只執行一次", "hourly": "每小時", "daily": "每天", "weekly": "每週"}
WEEKDAY_NAMES = ["一", "二", "三", "四", "五", "六", "日"]
SCHTASK_DAYS = ["MON", "TUE", "WED", "THU", "FRI", "SAT", "SUN"]


LANG_DEFAULT = {"python": "main.py", "py": "main.py", "javascript": "index.js", "js": "index.js",
                "typescript": "index.ts", "html": "index.html", "css": "style.css", "json": "data.json",
                "bash": "run.sh", "sh": "run.sh", "java": "Main.java", "c": "main.c", "cpp": "main.cpp",
                "go": "main.go", "rust": "main.rs", "rs": "main.rs", "sql": "schema.sql", "yaml": "config.yaml",
                "yml": "config.yaml", "markdown": "README.md", "md": "README.md", "text": "README.md"}
_PATH = re.compile(r"([A-Za-z0-9_.\-/\\]+\.[A-Za-z0-9]{1,6})")
_COMMENT_FIRST = re.compile(r"^\s*(?:#|//|--|<!--|/\*|;)?\s*(?:file|filename|檔名|檔案)?\s*[:：]?\s*([A-Za-z0-9_.\-/\\]+\.[A-Za-z0-9]{1,6})")


def _name_from_context(before_lines):
    for line in reversed(before_lines):
        line = line.strip().strip("*`#").strip()
        if not line or len(line) > 120:
            continue
        m = _PATH.search(line)
        if m and "." in m.group(1) and not m.group(1).startswith("."):
            cand = m.group(1).replace("\\", "/")
            if not re.match(r"^\d", cand) and " " not in cand:
                return cand.lstrip("/")
        if line and not m:
            break
    return ""


def _name_from_code(code, lang):
    first = code.splitlines()[:3]
    for line in first:
        m = _COMMENT_FIRST.match(line)
        if m:
            return m.group(1).replace("\\", "/").lstrip("/")
    return ""


CODE_LANGS = {"python","py","javascript","js","typescript","ts","html","css","json","java","c","cpp","c++","go",
              "rust","rs","sql","yaml","yml","php","ruby","rb","sh","bash","shell","kotlin","swift","scala","r",
              "xml","toml","ini","dockerfile","makefile","vue","jsx","tsx"}
_LOOKS_CODE = re.compile(r"(^#!|^\s*(import|from|def |class |function |const |let |var |package |public |private |"
                         r"#include|using |namespace|export |module|require\(|async |await |print\(|console\.|"
                         r"<\?php|<!DOCTYPE|<html|<\?xml|SELECT |CREATE |INSERT )|[{};]\s*$|=>|\)\s*:\s*$)",
                         re.I | re.M)


def _looks_like_code(code):
    return bool(_LOOKS_CODE.search(code))


KEEP_EXTS = {".txt", ".md", ".cfg", ".toml", ".ini", ".env", ".yaml", ".yml", ".csv", ".gitignore", ".bat"}
KEEP_NAMES = {"requirements.txt", "package.json", "dockerfile", "makefile", ".gitignore", ".env", ".env.example"}


def extract_code_project(text, max_files=20):
    """從 Markdown 文字抽出程式專案：回傳 [{"name","code","lang"}]。檔名取自程式碼區塊前的標題/路徑，或區塊內首行註解；
    都沒有時依語言給預設名。同名後出現的覆蓋前面的（模型常附「修正版」）。"""
    if not text:
        return []
    files = {}
    order = []
    pos = 0
    pattern = re.compile(r"```([^\n`]*)\n(.*?)```", re.DOTALL)
    used_default = set()
    lines = text.split("\n")
    # 以行為單位找出每個 code fence 的前文
    for m in pattern.finditer(text):
        info = (m.group(1) or "").strip().lower()
        code = m.group(2)
        if not code.strip():
            continue
        lang = re.split(r"[\s:]", info)[0] if info else ""
        before = text[:m.start()].split("\n")[-4:]
        name = _name_from_context(before) or _name_from_code(code, lang)
        if not name:
            # 標在 fence info 上，例如 ```python title=app.py
            m2 = _PATH.search(info)
            if m2:
                name = m2.group(1)
        if not name:
            if lang in ("", "text", "txt", "console", "shell", "output", "bash") and "python" not in info:
                continue  # 疑似終端輸出或純文字，不是檔案
            base = LANG_DEFAULT.get(lang, (lang or "file") + ".txt")
            if base in used_default:
                root, ext = os.path.splitext(base)
                base = f"{root}_{len(used_default)}{ext}"
            used_default.add(base)
            name = base
        name = name.strip().lstrip("/")
        if len(name) > 100 or ".." in name:
            continue
        base = name.rsplit("/", 1)[-1].lower()
        ext = os.path.splitext(base)[1]
        keep_doc = base in KEEP_NAMES or ext in KEEP_EXTS
        if lang not in CODE_LANGS and not _looks_like_code(code) and not keep_doc:
            continue                                  # 沒有程式語言標記、內容也不像程式碼、也不是已知設定/說明檔：跳過
        if name not in files:
            order.append(name)
        files[name] = {"name": name, "code": code.rstrip() + "\n", "lang": lang}
    return [files[n] for n in order]


def new_schedule():
    now = _dt.datetime.now() + _dt.timedelta(minutes=5)
    return {"id": "s" + uuid.uuid4().hex[:8], "name": "新排程", "enabled": True, "kind": "agent", "prompt": "",
            "workspace": "", "repeat": "daily", "time": now.strftime("%H:%M"), "date": now.strftime("%Y-%m-%d"),
            "weekdays": [now.weekday()], "approval": "deny", "close_after": True, "next": None,
            "last_run": "", "last_status": "", "windows_task": False, "on_battery": True}


def _parse_hhmm(text):
    m = re.match(r"^\s*(\d{1,2})[:：](\d{2})\s*$", text or "")
    if not m or int(m.group(1)) > 23 or int(m.group(2)) > 59:
        raise ValueError("時間格式要像 08:30")
    return int(m.group(1)), int(m.group(2))


def next_run_time(sch, after=None):
    """回傳下一次執行的時間（datetime），沒有下一次就回傳 None。"""
    after = after or _dt.datetime.now()
    hh, mm = _parse_hhmm(sch.get("time", ""))
    repeat = sch.get("repeat", "daily")
    if repeat == "once":
        try:
            day = _dt.datetime.strptime(sch.get("date", ""), "%Y-%m-%d")
        except ValueError:
            raise ValueError("日期格式要像 2026-10-25")
        when = day.replace(hour=hh, minute=mm)
        return when if when > after else None
    if repeat == "hourly":
        when = after.replace(minute=mm, second=0, microsecond=0)
        return when if when > after else when + _dt.timedelta(hours=1)
    base = after.replace(hour=hh, minute=mm, second=0, microsecond=0)
    if repeat == "daily":
        return base if base > after else base + _dt.timedelta(days=1)
    days = sorted({int(d) % 7 for d in (sch.get("weekdays") or [])}) or [after.weekday()]
    for offset in range(0, 8):
        when = base + _dt.timedelta(days=offset)
        if when.weekday() in days and when > after:
            return when
    return None


def describe_schedule(sch):
    rep = sch.get("repeat", "daily")
    if rep == "once":
        when = f"{sch.get('date')} {sch.get('time')}"
    elif rep == "hourly":
        when = f"每小時的第 {sch.get('time', '00:00').split(':')[-1]} 分"
    elif rep == "weekly":
        when = "每週" + "、".join(WEEKDAY_NAMES[int(d) % 7] for d in sorted(sch.get("weekdays") or [])) + f" {sch.get('time')}"
    else:
        when = f"每天 {sch.get('time')}"
    return f"{when}・{'Agent' if sch.get('kind') == 'agent' else 'AI 討論'}"


def schtasks_date(date_text, pattern=None):
    """schtasks /SD 要用系統的短日期格式（例如 zh-TW 是 yyyy/M/d）。"""
    day = _dt.datetime.strptime(date_text, "%Y-%m-%d")
    if pattern is None and sys.platform == "win32":
        try:
            import winreg
            with winreg.OpenKey(winreg.HKEY_CURRENT_USER, r"Control Panel\International") as k:
                pattern = winreg.QueryValueEx(k, "sShortDate")[0]
        except OSError:
            pattern = None
    pattern = pattern or "yyyy/MM/dd"
    if re.search(r"ddd|MMM|[^yMd/\-. ]", pattern):
        pattern = "yyyy/MM/dd"
    out = pattern
    for token, value in (("yyyy", f"{day.year:04d}"), ("yy", f"{day.year % 100:02d}"), ("MM", f"{day.month:02d}"),
                         ("M", str(day.month)), ("dd", f"{day.day:02d}"), ("d", str(day.day))):
        out = out.replace(token, "\0" + value + "\0")       # 用標記避免已替換的數字再被處理
    return out.replace("\0", "")


SCHEDULE_INBOX = os.path.join(LOG_DIR, "排程請求")


def check_windows_task_paths(schedules):
    """檢查已登錄到 Windows 工作排程器的排程，指向的程式／Python 路徑是否還存在（搬過資料夾或換環境後常失效）。
    回傳 [(排程, 問題說明)]；只在 Windows 上有意義。"""
    if os.name != "nt":
        return []
    problems = []
    for sch in schedules:
        if not sch.get("windows_task") or not sch.get("enabled", True):
            continue
        try:
            name, args = windows_task_command(sch, os.path.abspath(APP_DIR + os.sep + "AI協作.py"))
            q = subprocess.run(["schtasks", "/Query", "/TN", name, "/FO", "LIST", "/V"], capture_output=True,
                               text=True, encoding="cp950", errors="replace", timeout=15,
                               creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0))
        except (OSError, subprocess.SubprocessError):
            continue
        if q.returncode != 0:
            problems.append((sch, "Windows 工作排程器裡找不到這個排程（可能被移除）"))
            continue
        for line in q.stdout.splitlines():
            m = re.search(r'"([A-Za-z]:\\[^"]+\.exe)"', line)
            if m and not os.path.exists(m.group(1)):
                problems.append((sch, f"排程指向的程式不存在：{m.group(1)}（可能搬過資料夾或換過 Python 環境）"))
                break
    return problems


def post_schedule_request(sid, inbox=None):
    """Windows 排程啟動時，如果程式已經開著，就把「請執行排程 sid」交給開著的那一個（避免執行兩次、互相覆蓋設定）。"""
    inbox = inbox or SCHEDULE_INBOX
    os.makedirs(inbox, exist_ok=True)
    stamp = time.strftime("%Y%m%d_%H%M%S")
    path = os.path.join(inbox, f"{re.sub(r'[^0-9A-Za-z_-]', '_', sid)}_{stamp}_{uuid.uuid4().hex[:4]}.json")
    tmp = path + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump({"id": sid, "time": _dt.datetime.now().isoformat(timespec="seconds")}, f, ensure_ascii=False)
    safe_replace(tmp, path)
    return path


def take_schedule_requests(inbox=None):
    """取出待執行的排程請求，回傳 [(檔案路徑, 排程 id)]（舊的在前）。"""
    inbox = inbox or SCHEDULE_INBOX
    try:
        names = sorted(n for n in os.listdir(inbox) if n.endswith(".json"))
    except OSError:
        return []
    out = []
    for n in names:
        path = os.path.join(inbox, n)
        try:
            with open(path, encoding="utf-8") as f:
                data = json.load(f)
            out.append((path, str(data.get("id") or "")))
        except (OSError, ValueError):
            continue
    return out


def finish_schedule_request(path, inbox=None):
    """處理完的請求移到「已處理」（不刪除）。"""
    done = os.path.join(inbox or SCHEDULE_INBOX, "已處理")
    try:
        os.makedirs(done, exist_ok=True)
        os.replace(path, os.path.join(done, os.path.basename(path)))
    except OSError:
        pass


def windows_battery_command(task_name, allow=True):
    """Windows 預設「用電池時不啟動、改用電池就停止」，筆電沒插電時排程會悄悄不執行。
    用 PowerShell 改這個工作的電源條件（schtasks 指令本身沒有這個選項）。回傳指令參數清單。"""
    folder, _sep, leaf = task_name.rpartition("\\")
    q = lambda s: "'" + s.replace("'", "''") + "'"
    flag = "$false" if allow else "$true"
    script = (f"$t = Get-ScheduledTask -TaskPath {q(chr(92) + folder + chr(92))} -TaskName {q(leaf)}; "
              f"$t.Settings.DisallowStartIfOnBatteries = {flag}; $t.Settings.StopIfGoingOnBatteries = {flag}; "
              "Set-ScheduledTask -InputObject $t | Out-Null")
    return ["powershell", "-NoProfile", "-NonInteractive", "-Command", script]


DATA_FOLDERS = ("工作階段", "紀錄", "日誌", "備份", "dist", "build")


def folder_sizes(base=None):
    """各資料夾佔用的空間（位元組），讓使用者知道哪裡在長大。"""
    base = base or APP_DIR
    out = {}
    for name in DATA_FOLDERS:
        total = 0
        for root, _dirs, files in os.walk(os.path.join(base, name)):
            for f in files:
                try:
                    total += os.path.getsize(os.path.join(root, f))
                except OSError:
                    pass
        out[name] = total
    return out


def archive_old_files(folder, days=90, now=None, skip=()):
    """把資料夾第一層、超過 days 天沒改過的檔案移到「封存/年月」（不刪除）。回傳移動的檔案數。
    紀錄的 .md 與 .json 是同名一組，會一起移。"""
    now = now or time.time()
    try:
        names = os.listdir(folder)
    except OSError:
        return 0
    moved = 0
    for n in names:
        src = os.path.join(folder, n)
        if not os.path.isfile(src) or n.endswith((".tmp", ".lock")) or n in skip:
            continue
        try:
            mtime = os.path.getmtime(src)
        except OSError:
            continue
        if now - mtime < days * 86400:
            continue
        dest_dir = os.path.join(folder, "封存", time.strftime("%Y%m", time.localtime(mtime)))
        try:
            os.makedirs(dest_dir, exist_ok=True)
            dest = os.path.join(dest_dir, n)
            if os.path.exists(dest):
                root, ext = os.path.splitext(n)
                dest = os.path.join(dest_dir, f"{root}_{int(mtime)}{ext}")
            os.replace(src, dest)
            moved += 1
        except OSError:
            continue
    return moved


def human_size(n):
    for unit in ("B", "KB", "MB", "GB"):
        if n < 1024 or unit == "GB":
            return f"{n:.0f} {unit}" if unit == "B" else f"{n:.1f} {unit}"
        n /= 1024


def windows_task_command(sch, script_path, python_exe=None):
    """組出 schtasks 建立工作的參數（程式沒開時也會由 Windows 啟動並執行這個排程）。"""
    exe = python_exe or sys.executable
    pyw = os.path.join(os.path.dirname(exe), "pythonw.exe")
    if os.path.exists(pyw) and not FROZEN:
        exe = pyw
    name = "AI協作\\" + re.sub(r'[\\/:*?"<>|]', "_", sch.get("name") or sch["id"])[:60] + "_" + sch["id"]
    hh, mm = _parse_hhmm(sch.get("time", ""))
    args = ["schtasks", "/Create", "/F", "/TN", name,
            "/TR", (f'"{exe}" --run-schedule {sch["id"]}' if FROZEN else
                    f'"{exe}" "{os.path.abspath(script_path)}" --run-schedule {sch["id"]}'), "/ST", f"{hh:02d}:{mm:02d}"]
    rep = sch.get("repeat", "daily")
    if rep == "once":
        args += ["/SC", "ONCE", "/SD", schtasks_date(sch.get("date", ""))]
    elif rep == "hourly":
        args += ["/SC", "HOURLY"]
    elif rep == "weekly":
        args += ["/SC", "WEEKLY", "/D", ",".join(SCHTASK_DAYS[int(d) % 7] for d in sorted(sch.get("weekdays") or [0]))]
    else:
        args += ["/SC", "DAILY"]
    return name, args


# ───────────────────────── 更新 ─────────────────────────
def source_version(text):
    m = re.search(r'^APP_VERSION\s*=\s*"([\d.]+)"', text or "", re.M)
    return m.group(1) if m else ""


def version_tuple(v):
    return tuple(int(x) for x in re.findall(r"\d+", v or "0"))


def apply_update(new_text, target=None, expected_sha256=None):
    """用新版的 AI協作.py 取代目前的程式：先檢查 SHA-256（有給的話）、語法與版本號，舊檔備份到 備份/更新前_v版本_時間/，再寫入。"""
    target = target or os.path.join(APP_DIR, "AI協作.py")
    if expected_sha256:
        verify_update_hash(new_text, expected_sha256)
    version = source_version(new_text)
    if not version:
        raise ValueError("這不是 AI協作.py（找不到 APP_VERSION）")
    compile(new_text, "AI協作.py", "exec")            # 語法有錯就不更新
    if version_tuple(version) <= version_tuple(APP_VERSION):
        raise ValueError(f"新檔的版本 {version} 沒有比目前的 {APP_VERSION} 新")
    # 備份放在被更新的檔案旁邊（原本固定放程式資料夾，自我測試會在使用者的資料夾留下測試用的備份）
    backup_dir = os.path.join(os.path.dirname(os.path.abspath(target)), "備份",
                              f"更新前_v{APP_VERSION}_{time.strftime('%Y%m%d_%H%M%S')}")
    os.makedirs(backup_dir, exist_ok=True)
    if os.path.exists(target):
        shutil.copy2(target, os.path.join(backup_dir, os.path.basename(target)))
    tmp = target + ".new"
    with open(tmp, "w", encoding="utf-8", newline="\n") as f:
        f.write(new_text)
    safe_replace(tmp, target)
    return version, backup_dir


def fetch_update(url, timeout=30):
    if not re.match(r"^https?://", url or ""):
        raise ValueError("更新網址要用 http:// 或 https:// 開頭（例如 GitHub 的 raw 檔案網址）")
    if url.lower().startswith("http://") and not _is_local_or_private_url(url):
        raise ValueError("更新檔要用 https:// 下載（http:// 沒有加密，途中可能被換成惡意程式）")
    req = urllib.request.Request(url, headers={"User-Agent": "AI-Workbench/" + APP_VERSION})   # 標頭只能用 ASCII
    with urllib.request.urlopen(req, timeout=timeout) as resp:
        final = resp.geturl() or url
        if final.lower().startswith("http://") and not _is_local_or_private_url(final):
            raise ValueError("更新網址被轉到未加密的 http://，可能被換成惡意程式，已停止")    # v6.11
        return resp.read(5_000_000).decode("utf-8")
# ═════════════════════════ 6. 協作拓樸圖 ═════════════════════════
# 中央（或上方）是主持 AI，周圍是各角色 AI；虛線是訊息通道，小光點代表訊息往來。
# 版面依 AI 數量自動切換：
#   1～8 位：「環繞」版面——左右兩側環繞主持 AI，每位旁邊有一張資訊卡。
#   9 位以上：「陣列」版面——主持 AI 在上方，所有 AI 以格狀排列並以匯流線相連。
# 畫布不夠大時整張圖等比縮小，保證元件不重疊。


def rounded_points(x1, y1, x2, y2, r):
    r = max(0, min(r, (x2 - x1) / 2, (y2 - y1) / 2))
    return [x1 + r, y1, x2 - r, y1, x2, y1, x2, y1 + r, x2, y2 - r, x2, y2,
            x2 - r, y2, x1 + r, y2, x1, y2, x1, y2 - r, x1, y1 + r, x1, y1]


def short_model(model):
    """「deepseek-ai/deepseek-v4.1-flash」→「deepseek-v4.1-flash」（廠商前綴佔空間，完整名稱放在提示框）。"""
    return (model or "").rstrip("/").split("/")[-1]


def _bezier(a, c, b, steps=24):
    pts = []
    for i in range(steps + 1):
        t = i / steps
        pts.append(((1 - t) ** 2 * a[0] + 2 * (1 - t) * t * c[0] + t * t * b[0],
                    (1 - t) ** 2 * a[1] + 2 * (1 - t) * t * c[1] + t * t * b[1]))
    return pts


def _make_topology_class():
    """tkinter 載入後才建立類別（讓 --selftest 不需要 tkinter）。"""

    class TopologyView(tk.Canvas):
        CARD_MAX = 8          # 超過這個數量改用陣列版面

        def __init__(self, master, theme, family, scale=1.0, callbacks=None):
            super().__init__(master, bg=theme["canvas"], highlightthickness=0, bd=0)
            self.t = theme
            self.base = scale
            self.s = scale
            self.cb = callbacks or {}
            self.agents, self.hub, self.mode = [], None, MODE_SYNTH
            self.states, self.details, self.previews = {}, {}, {}
            self.selected = None
            self.ranks = {}          # pid → 互評平均名次
            self.agent_view = False  # True：Agent 模式（中央是 Agent，周圍是工具類別）
            self.tip_pid = None
            self.phase, self.round_text, self.final_preview = "待命", "共享脈絡", ""
            self.running = False
            self.pos, self.anchor, self.paths, self.eyes, self.card_geom = {}, {}, {}, {}, {}
            self.sprites = {}            # pid → (圖片項目, 各格圖片, 起始格)：會動的角色
            self._sprite_cache, self._sprite_used = {}, set()
            self.packets, self.flow_timer = [], {}
            self.hub_arc, self.arc_angle, self.frame = None, 0, 0
            self.layout_kind = "cards"
            self.final_geom = None
            self._redraw_job = None
            self.f = {k: tkfont.Font(family=family, size=v[0], weight=v[1]) for k, v in
                      {"title": (10, "bold"), "small": (8, "normal"), "body": (9, "normal"),
                       "hub": (11, "bold"), "icon": (7, "bold")}.items()}
            self.f["icon"].configure(family=DEFAULT_MONO_FONT)
            self.bind("<Configure>", lambda _e: self._schedule_redraw())
            self.after(40, self._animate)

        # ───────────── 對外介面 ─────────────
        def set_theme(self, theme, family):
            self.t = theme
            for key in ("title", "small", "body", "hub"):
                self.f[key].configure(family=family)
            self.configure(bg=theme["canvas"])
            self._schedule_redraw()

        def set_participants(self, agents, hub, mode):
            self.agents, self.hub, self.mode = list(agents), hub, mode
            for a in self.agents:
                if not a.get("enabled", True):
                    self.states[a["id"]] = "disabled"
                elif self.states.get(a["id"]) in (None, "disabled"):
                    self.states[a["id"]] = "idle"
            self._schedule_redraw()

        def reset_run(self):
            for a in self.agents:
                self.states[a["id"]] = "idle" if a.get("enabled", True) else "disabled"
                self.details[a["id"]] = self.previews[a["id"]] = ""
            self.states[HUB_ID] = "idle"
            self.details[HUB_ID] = self.previews[HUB_ID] = ""
            self.ranks = {}
            self.final_preview = ""
            self.packets.clear()
            self.redraw()

        def set_state(self, pid, status, detail=None):
            self.states[pid] = status
            if detail is not None:
                self.details[pid] = detail
            self._update_node(pid)

        def set_preview(self, pid, text):
            self.previews[pid] = text
            self._update_node(pid)

        def set_final(self, text):
            self.final_preview = text or ""
            if self.final_geom:
                self.itemconfigure("final_text", text=self._fit(self.final_preview or "完成後點這裡查看",
                                                                self.f["small"], self.final_geom))

        def set_phase(self, phase, round_text=None):
            self.phase = phase
            if round_text is not None:
                self.round_text = round_text
            self.itemconfigure("phase_text", text=phase)
            self.itemconfigure("context_text", text=self.round_text)

        def set_running(self, running):
            self.running = running
            self.flow_timer.clear()
            self.itemconfigure("phase_dot", fill=self.t["accent"] if running else self.t["line"])

        def select(self, pid):
            self.selected = pid
            self.redraw()

        def pulse_link(self, src, dst, kind="review"):
            path = self._link_path(src, dst, kind)
            if path:
                self._spawn(path, self._color(src), size=5, speed=0.03)

        # ───────────── 顏色與文字 ─────────────
        def _schedule_redraw(self):
            if self._redraw_job:
                self.after_cancel(self._redraw_job)
            self._redraw_job = self.after(60, self.redraw)

        def _agent(self, pid):
            return next((a for a in self.agents if a["id"] == pid), None)

        def _color(self, pid):
            if pid == HUB_ID:
                return self.t["hub"]
            a = self._agent(pid)
            if a and not a.get("enabled", True):
                return mix(self.t["muted"], self.t["canvas"], 0.3)
            return self.t.role_color(a.get("role") if a else DEFAULT_ROLE)

        def _light(self, pid):
            if pid == HUB_ID:
                return self.t["hub_light"]
            a = self._agent(pid)
            if a and not a.get("enabled", True):
                return mix(self.t["muted"], self.t["canvas"], 0.82)
            return self.t.role_light(a.get("role") if a else DEFAULT_ROLE)

        def _fit(self, text, font, width, lines=1):
            text = " ".join((text or "").split())
            if not text or width <= 10:
                return ""
            budget = width * lines * 0.94
            if font.measure(text) <= budget:
                return text
            lo, hi = 0, len(text)
            while lo < hi:
                mid = (lo + hi + 1) // 2
                if font.measure(text[:mid] + "…") <= budget:
                    lo = mid
                else:
                    hi = mid - 1
            return text[:lo] + "…"

        # ───────────── 繪圖基本元件 ─────────────
        def _rrect(self, x1, y1, x2, y2, r, **kw):
            return self.create_polygon(rounded_points(x1, y1, x2, y2, r), smooth=True, **kw)

        def _card(self, x1, y1, x2, y2, tags, outline=None, width=1, r=12):
            s = self.s
            self._rrect(x1, y1 + 3 * s, x2, y2 + 4 * s, r * s, fill=self.t["shadow"], outline="", tags=tags)
            return self._rrect(x1, y1, x2, y2, r * s, fill=self.t["surface"], outline=outline or self.t["border"],
                               width=width, tags=tags)

        # ───────────── 動態角色（「機器人動畫」資料夾的逐格圖） ─────────────
        # 有素材時拓樸圖用會動的角色；找不到素材或讀取失敗時，_robot 改用下面程式畫的造型。
        def _sprite_frames(self, look, want):
            path, size = robot_sprite_file(look, want)
            if not path:
                return None
            key = (path, size)
            frames = self._sprite_cache.get(key)
            if frames is None:
                frames = []
                try:
                    sheet = tk.PhotoImage(master=self, file=path)
                    count = sheet.width() // size
                    if count >= ROBOT_SPRITE_FRAMES + 1 and sheet.height() >= size:
                        for i in range(ROBOT_SPRITE_FRAMES + 1):
                            img = tk.PhotoImage(master=self, width=size, height=size)
                            img.tk.call(img, "copy", sheet, "-from", i * size, 0, (i + 1) * size, size,
                                        "-to", 0, 0, "-compositingrule", "set")
                            frames.append(img)
                    del sheet
                except tk.TclError as e:          # 例如 Tk 太舊讀不了 PNG：記住失敗，之後用程式畫的造型
                    logging.getLogger("ai_collab.ui").warning("讀取動態角色失敗 %s：%s", path, e)
                    frames = []
                self._sprite_cache[key] = frames
            self._sprite_used.add(key)
            return (frames, size) if frames else None

        def _sprite_dim(self, pid):
            """停用的 AI、此模式用不到的主持 AI：顯示淡灰定格。"""
            if pid == HUB_ID:
                return not (self.agent_view or self.mode in (MODE_SYNTH, MODE_REVIEW, MODE_PLAN))
            a = self._agent(pid)
            return bool(a and not a.get("enabled", True))

        def _sprite_robot(self, pid, cx, cy, k, color, light, tags, look):
            s = self.s * k
            got = self._sprite_frames(look, 112 * s)
            if not got:
                return False
            frames, _size = got
            t = self.t

            def oval(x1, y1, x2, y2, **kw):
                self.create_oval(cx + x1 * s, cy + y1 * s, cx + x2 * s, cy + y2 * s, tags=tags, **kw)

            # 底座和程式畫的造型一樣，顏色跟著身分與狀態
            oval(-46, 30, 46, 54, fill=mix(light, t["shadow"], 0.45), outline="")
            oval(-44, 22, 44, 48, fill=light, outline=color, width=max(1, 2 * self.s))
            oval(-30, 27, 30, 41, fill=mix(light, t["surface"], 0.5), outline="")
            if self._sprite_dim(pid):
                self.create_image(cx, cy - 8 * s, image=frames[ROBOT_SPRITE_FRAMES], tags=tags)
                return True
            # 每位的起始格錯開，不會整齊劃一地動
            phase = int(hashlib.md5(str(pid).encode("utf-8")).hexdigest(), 16) % ROBOT_SPRITE_FRAMES
            index = (self.frame // 2 + phase) % ROBOT_SPRITE_FRAMES if self.t.animate else ROBOT_SPRITE_STILL
            item = self.create_image(cx, cy - 8 * s, image=frames[index], tags=tags)
            self.sprites[pid] = (item, frames, phase)
            return True

        # ───────────── Q 版機器人：原創造型「協作小隊」（沒有動態素材時使用） ─────────────
        # 全家共同特徵：麻糬形大頭、深色螢幕臉＋發光大眼與腮紅、兩側六角耳螺絲、圓圓小身體與短腳、圓形底座。
        # 每個身分各有自己的道具，一眼就能分辨工作：
        #   一般助理＝星星天線＋小領巾、揮手　　程式專家＝耳罩耳機＋筆電　　研究分析＝探險帽＋放大鏡
        #   對話溝通＝對話框天線＋耳麥　　　　　文件撰寫＝貝雷帽＋大鉛筆　　資料處理＝資料庫帽＋長條圖平板
        #   審查批判＝方帽＋認真眉毛＋打勾夾板　主持 AI＝節點光環＋領結＋指揮棒　Agent＝工程帽＋扳手＋工具腰帶
        ROBOT_PROP_INK = {"pencil": "#F3BE45", "pencil_tip": "#F4DDBB", "eraser": "#F29BB0", "lead": "#4A4A55",
                          "blush": "#FF7FA0", "spark": "#FFFFFF"}

        def _robot(self, pid, cx, cy, k, color, light, tags, look=None):
            s = self.s * k
            t = self.t
            look = look if look in ROBOT_LOOKS else DEFAULT_ROLE
            if self._sprite_robot(pid, cx, cy, k, color, light, tags, look):
                return
            ink, shell = t["robot_line"], t["robot"]
            lw = max(1, 1.3 * s)
            prop = self.ROBOT_PROP_INK

            def P(*xy):
                return [v * s + (cx if i % 2 == 0 else cy) for i, v in enumerate(xy)]

            def oval(x1, y1, x2, y2, **kw):
                return self.create_oval(*P(x1, y1, x2, y2), tags=tags, **kw)

            def rr(x1, y1, x2, y2, r, **kw):
                return self._rrect(*P(x1, y1, x2, y2), r * s, tags=tags, **kw)

            def poly(pts, **kw):
                return self.create_polygon(*P(*pts), tags=tags, **kw)

            def line(pts, w=1.6, **kw):
                return self.create_line(*P(*pts), width=max(1, w * s), capstyle="round", joinstyle="round",
                                        tags=tags, **kw)

            def arc(x1, y1, x2, y2, start, extent, w=1.6, **kw):
                return self.create_arc(*P(x1, y1, x2, y2), start=start, extent=extent, style="arc",
                                       width=max(1, w * s), tags=tags, **kw)

            def star(x, y, r, points=4, inner=0.42, **kw):
                pts = []
                for i in range(points * 2):
                    rad = r if i % 2 == 0 else r * inner
                    a = math.radians(180 / points * i - 90)
                    pts += [x + rad * math.cos(a), y + rad * math.sin(a)]
                return poly(pts, **kw)

            def hexagon(x, y, r, **kw):
                return poly([v for i in range(6) for v in (x + r * math.cos(math.radians(60 * i)),
                                                           y + r * math.sin(math.radians(60 * i)))], **kw)

            def arm(side, raised=False):
                d = 1 if side == "right" else -1
                if raised:
                    pts, hand = [13 * d, 6, 22 * d, -3, 27 * d, 0, 19 * d, 12], (25 * d, -3)
                else:
                    pts, hand = [13 * d, 8, 22 * d, 13, 21 * d, 20, 13 * d, 17], (22 * d, 19)
                poly(pts, smooth=True, fill=shell, outline=ink, width=lw)
                oval(hand[0] - 4, hand[1] - 4, hand[0] + 4, hand[1] + 4, fill=color, outline="")

            # 底座與影子
            oval(-46, 30, 46, 54, fill=mix(light, t["shadow"], 0.45), outline="")
            oval(-44, 22, 44, 48, fill=light, outline=color, width=max(1, 2 * self.s))
            oval(-30, 27, 30, 41, fill=mix(light, t["surface"], 0.5), outline="")
            # 腳、身體、肚子
            oval(-13, 25, -3, 34, fill=color, outline="")
            oval(3, 25, 13, 34, fill=color, outline="")
            rr(-15, 2, 15, 31, 11, fill=shell, outline=ink, width=lw)
            oval(-9, 11, 9, 27, fill=light, outline="")
            oval(-3, 16, 3, 22, fill=color, outline="")

            # 手（拿道具的那隻手在後面畫）
            raised_left = look in ("對話溝通",)
            raised_right = look in ("一般助理",)
            if look not in ("程式專家", "審查批判"):
                arm("left", raised_left)
            if look not in ("程式專家", "研究分析", "文件撰寫", "資料處理", "主持", "Agent"):
                arm("right", raised_right)

            # 身體上的配件
            if look == "一般助理":
                poly([-11, 3, 11, 3, 0, 12], fill=color, outline="")
            elif look == "主持":
                poly([-9, 2, -1, 6, -9, 10], fill=color, outline="")
                poly([9, 2, 1, 6, 9, 10], fill=color, outline="")
                oval(-2.5, 3.5, 2.5, 8.5, fill=mix(color, "#000000", 0.2), outline="")
            elif look == "Agent":
                rr(-15, 19, 15, 24, 2, fill=color, outline="")
                rr(-4, 18, 4, 25, 1.5, fill=mix(color, "#FFFFFF", 0.45), outline="")

            # 頭
            rr(-31, -38, 31, 8, 20, fill=shell, outline=ink, width=lw)
            if look not in ("程式專家",):
                for x in (-32, 32):
                    hexagon(x, -15, 5, fill=color, outline="")
                    oval(x - 1.6, -16.6, x + 1.6, -13.4, fill=mix(color, "#FFFFFF", 0.5), outline="")
            rr(-23, -30, 23, 0, 13, fill=t["visor"], outline="")
            line([-17, -26.5, -11, -27.5], w=1.4, fill=mix(t["visor"], "#FFFFFF", 0.3))
            # 臉：大眼睛（含亮點，眨眼時一起闔上）、嘴巴、腮紅
            eyes = []
            for ex in (-10, 10):
                c1 = P(ex - 5.5, -23, ex + 5.5, -10)
                if look == "程式專家":          # 方形像素眼
                    c1 = P(ex - 5, -22, ex + 5, -11)
                    item = self.create_rectangle(*c1, fill=t["eye"], outline="", tags=tags)
                else:
                    item = self.create_oval(*c1, fill=t["eye"], outline="", tags=tags)
                eyes.append((item, c1))
                c2 = P(ex - 3.2, -21, ex - 0.2, -17.6)
                eyes.append((self.create_oval(*c2, fill=prop["spark"], outline="", tags=tags), c2))
            self.eyes[pid] = eyes
            if look == "對話溝通":              # 張嘴說話
                self.create_arc(*P(-4.5, -11, 4.5, -2), start=180, extent=180, style="chord", fill=t["eye"],
                                outline="", tags=tags)
            else:
                arc(-4, -10.5, 4, -3.5, 205, 130, w=1.4, outline=t["eye"])
            for bx in (-18, 14):
                oval(bx, -8.5, bx + 5, -5, fill=mix(t["visor"], prop["blush"], 0.6), outline="")
            if look == "審查批判":
                line([-16, -27, -6, -24.5], w=1.6, fill=t["eye"])
                line([16, -27, 6, -24.5], w=1.6, fill=t["eye"])

            # 頭上的配件與手上的道具
            if look == "一般助理":
                line([0, -38, 0, -46], w=1.8, fill=ink)
                star(0, -50, 6.5, fill=color, outline="")
                star(0, -50, 2.4, fill=mix(color, "#FFFFFF", 0.6), outline="")
            elif look == "程式專家":
                arc(-35, -47, 35, 12, 18, 144, w=3.2, outline=color)
                for x1 in (-38, 29):
                    rr(x1, -23, x1 + 9, -5, 4, fill=color, outline="")
                arm("left")
                arm("right")
                poly([-17, 22, 17, 22, 20, 28, -20, 28], fill=ink, outline="")
                rr(-13, 8, 13, 23, 2.5, fill=t["visor"], outline=ink, width=lw)
                for y, x2 in ((12.5, -1), (15.5, 6), (18.5, 2)):
                    line([-8, y, x2, y], w=1.3, fill=color)
            elif look == "研究分析":
                oval(-30, -38, 30, -30, fill=color, outline="")
                rr(-18, -51, 18, -33, 9, fill=color, outline="")
                line([-17, -38, 17, -38], w=2, fill=mix(color, "#FFFFFF", 0.45))
                line([25, -2, 30, -8], w=3, fill=ink)
                oval(25, -24, 43, -6, fill=mix(light, t["surface"], 0.35), outline=color, width=max(1, 3 * s))
                arc(28, -21, 40, -9, 100, 70, w=1.4, outline=prop["spark"])
                arm("right", True)
            elif look == "對話溝通":
                arc(-35, -47, 35, 12, 30, 120, w=2, outline=ink)
                rr(-38, -21, -30, -7, 3.5, fill=color, outline="")
                line([-34, -8, -27, 2, -15, 3], w=1.6, fill=ink)
                oval(-17, 0.5, -12, 5.5, fill=color, outline="")
                line([8, -38, 12, -46], w=1.8, fill=ink)
                rr(6, -62, 32, -46, 6, fill=color, outline="")
                poly([12, -47, 9, -41, 17, -47], fill=color, outline="")
                for dx in (12, 19, 26):
                    oval(dx - 1.6, -55.6, dx + 1.6, -52.4, fill=prop["spark"], outline="")
            elif look == "文件撰寫":
                poly([-29, -33, -22, -44, -2, -48, 20, -43, 24, -35], smooth=True, fill=color, outline="")
                line([-1, -47, 1, -52], w=2, fill=color)
                poly([20, 16, 36, -8, 41, -5, 25, 19], fill=prop["pencil"], outline=ink, width=lw)
                poly([36, -8, 41, -5, 41.5, -14], fill=prop["pencil_tip"], outline=ink, width=lw)
                poly([39.6, -11.5, 41.2, -10.4, 41.5, -14], fill=prop["lead"], outline="")
                poly([20, 16, 25, 19, 23, 22, 18, 19], fill=prop["eraser"], outline="")
                arm("right", True)
            elif look == "資料處理":
                rr(-13, -49, 13, -36, 3, fill=color, outline="")
                oval(-13, -52, 13, -46, fill=mix(color, "#FFFFFF", 0.35), outline="")
                arc(-13, -46, 13, -40, 180, 180, w=1.4, outline=mix(color, "#FFFFFF", 0.5))
                arm("right")
                rr(14, 4, 36, 24, 3, fill=t["visor"], outline=ink, width=lw)
                for x, top in ((19, 15), (25, 9), (31, 12)):
                    line([x, 20, x, top], w=3, fill=color)
            elif look == "審查批判":
                rr(-13, -44, 13, -35, 3, fill=mix(color, "#000000", 0.18), outline="")
                poly([-26, -43, 0, -51, 26, -43, 0, -36], fill=color, outline="")
                line([18, -42, 22, -33], w=1.4, fill=mix(color, "#000000", 0.25))
                oval(20, -34, 24, -30, fill=mix(color, "#000000", 0.25), outline="")
                arm("right")
                rr(-38, 3, -18, 27, 2.5, fill=t["surface"], outline=ink, width=lw)
                rr(-32, 1, -24, 6, 1.5, fill=color, outline="")
                line([-33, 15, -29, 20, -22, 10], w=2.4, fill=color)
                arm("left")
            elif look == "主持":
                oval(-23, -55, 23, -46, outline=color, width=max(1, 2 * s))
                for nx, ny in ((-21, -50.5), (21, -50.5), (0, -55)):
                    oval(nx - 3, ny - 3, nx + 3, ny + 3, fill=color, outline=t["surface"], width=max(1, s))
                line([24, -3, 36, -16], w=2, fill=ink)
                star(37, -17, 5.5, points=5, inner=0.45, fill=color, outline="")
                arm("right", True)
            elif look == "Agent":
                rr(-24, -51, 24, -34, 13, fill=color, outline="")
                rr(-31, -38, 31, -32, 3, fill=color, outline="")
                line([0, -50, 0, -37], w=2.4, fill=mix(color, "#FFFFFF", 0.4))
                star(32, -12, 9, points=8, inner=0.72, fill=mix(color, "#1A1A22", 0.35), outline="")
                oval(29, -15, 35, -9, fill=light, outline="")
                arm("right", True)

        def _badge(self, cx, cy, icon, color, tags, k=1.0):
            s = self.s * k
            r = 11 * s
            w = "#FFFFFF"
            self.create_oval(cx - r, cy - r, cx + r, cy + r, fill=color, outline=self.t["surface"],
                             width=max(1, 2 * self.s), tags=tags)
            lw = max(1, 1.6 * s)
            if icon == "code":
                self.create_text(cx, cy, text="</>", fill=w, font=self.f["icon"], tags=tags)
            elif icon == "search":
                self.create_oval(cx - 5 * s, cy - 5 * s, cx + 2 * s, cy + 2 * s, outline=w, width=lw, tags=tags)
                self.create_line(cx + 1 * s, cy + 1 * s, cx + 5 * s, cy + 5 * s, fill=w, width=lw, tags=tags)
            elif icon == "chat":
                self._rrect(cx - 6 * s, cy - 5 * s, cx + 6 * s, cy + 3 * s, 3 * s, fill=w, outline="", tags=tags)
                self.create_polygon(cx - 3 * s, cy + 2 * s, cx - 5 * s, cy + 7 * s, cx + 1 * s, cy + 2 * s, fill=w,
                                    outline="", tags=tags)
            elif icon == "doc":
                self.create_rectangle(cx - 4.5 * s, cy - 6 * s, cx + 4.5 * s, cy + 6 * s, outline=w, width=lw,
                                      tags=tags)
                for dy in (-2, 1, 4):
                    self.create_line(cx - 2.5 * s, cy + dy * s, cx + 2.5 * s, cy + dy * s, fill=w, tags=tags)
            elif icon == "db":
                self.create_oval(cx - 5 * s, cy - 6 * s, cx + 5 * s, cy - 2 * s, outline=w, width=lw, tags=tags)
                self.create_line(cx - 5 * s, cy - 4 * s, cx - 5 * s, cy + 4 * s, fill=w, width=lw, tags=tags)
                self.create_line(cx + 5 * s, cy - 4 * s, cx + 5 * s, cy + 4 * s, fill=w, width=lw, tags=tags)
                self.create_arc(cx - 5 * s, cy + 2 * s, cx + 5 * s, cy + 6 * s, start=180, extent=180, style="arc",
                                outline=w, width=lw, tags=tags)
            elif icon == "check":
                self.create_line(cx - 5 * s, cy, cx - 1.5 * s, cy + 4 * s, cx + 5 * s, cy - 4 * s, fill=w,
                                 width=max(1, 2 * s), tags=tags)
            elif icon == "hub":
                for i in range(6):
                    a = math.radians(60 * i)
                    self.create_line(cx, cy, cx + 6 * s * math.cos(a), cy + 6 * s * math.sin(a), fill=w, tags=tags)
                self.create_oval(cx - 3 * s, cy - 3 * s, cx + 3 * s, cy + 3 * s, fill=w, outline="", tags=tags)
            else:
                pts = []
                for i in range(8):
                    rr = (6 if i % 2 == 0 else 2.2) * s
                    a = math.radians(45 * i - 90)
                    pts += [cx + rr * math.cos(a), cy + rr * math.sin(a)]
                self.create_polygon(pts, fill=w, outline="", tags=tags)

        def _chip(self, pid, x_right, y_mid, max_w, tags):
            """狀態膠囊（右對齊），回傳膠囊寬度。"""
            s = self.s
            text, color = self.t.status(self.states.get(pid, "idle"))
            detail = self.details.get(pid) or ""
            label = self._fit(text + (f" {detail}" if detail else ""), self.f["small"], max_w)
            w = self.f["small"].measure(label) + 20 * s
            self._rrect(x_right - w, y_mid - 9 * s, x_right, y_mid + 9 * s, 9 * s,
                        fill=mix(color, self.t["surface"], 0.85), outline="", tags=tags + (f"chipbg:{pid}",))
            self.create_oval(x_right - w + 7 * s, y_mid - 3 * s, x_right - w + 13 * s, y_mid + 3 * s, fill=color,
                             outline="", tags=tags + (f"chipdot:{pid}",))
            self.create_text(x_right - w + 16 * s, y_mid, text=label, anchor="w", fill=color, font=self.f["small"],
                             tags=tags + (f"chip:{pid}",))
            return w

        # ───────────── 主要繪製 ─────────────
        def redraw(self):
            self._redraw_job = None
            self.delete("all")
            for d in (self.pos, self.anchor, self.paths, self.eyes, self.card_geom, self.sprites):
                d.clear()
            self.packets.clear()
            self._sprite_used = set()
            w, h = max(self.winfo_width(), 300), max(self.winfo_height(), 140)   # 高度不能假裝成 300，否則矮的區域會被裁掉
            # 版面：畫布又寬又矮（例如放在對話串上方）→ 橫帶版面；否則 1～8 位環繞、9 位以上陣列
            band_fit, band_rows = self._band_fit(w, h)
            cards_fit = min(1.0, w / (1000 * self.base), h / (640 * self.base))
            if self.agents and w / max(1, h) >= 1.7 and band_fit > cards_fit * 1.15:
                self.layout_kind, fit, self.band_rows = "band", band_fit, band_rows
            elif len(self.agents) <= self.CARD_MAX:
                self.layout_kind, fit = "cards", cards_fit
            else:
                self.layout_kind, fit = "grid", self._grid_fit(w, h)
            self.s = self.base * max(0.34 if self.layout_kind == "band" else 0.42, fit)
            ratio = self.s / self.base
            for key, size, low in (("title", 10, 7), ("small", 8, 6), ("body", 9, 7), ("hub", 11, 8), ("icon", 7, 5)):
                self.f[key].configure(size=max(low, round(size * ratio)))
            if self.t.show_grid:
                self._draw_backdrop(w, h)
            if self.layout_kind == "cards":
                self._draw_cards_layout(w, h)
            elif self.layout_kind == "band":
                self._draw_band_layout(w, h)
            else:
                self._draw_grid_layout(w, h)
            self._draw_header()
            if not self.agents:
                self.create_text(w / 2, h - 40 * self.s, text="還沒有任何 AI，請用工具列的「AI 數量」或「端點」分頁新增。",
                                 fill=self.t["muted"], font=self.f["body"])
            # 動態角色的快取只留這次畫面用到的尺寸（視窗縮放後舊尺寸就用不到了）
            if len(self._sprite_cache) > 2 * len(ROBOT_SPRITE_KEYS):
                for key in [k for k in self._sprite_cache if k not in self._sprite_used]:
                    del self._sprite_cache[key]

        def _draw_backdrop(self, w, h):
            step = int(max(18, 28 * self.s))
            color = self.t["grid"]
            # 背景點陣畫成一張圖片並快取：原本每次重畫都建立數百個小圓點，會讓畫面變慢
            key = (int(w), int(h), step, color)
            if getattr(self, "_bg_key", None) != key:
                img = tk.PhotoImage(width=int(w), height=int(h))
                xs = range(step // 2, int(w), step)
                for y in range(step // 2, int(h) - 1, step):
                    for x in xs:
                        if x + 2 <= int(w):
                            img.put(color, to=(x - 1, y - 1, x + 1, y + 1))
                self._bg_img, self._bg_key = img, key
            self.create_image(0, 0, image=self._bg_img, anchor="nw")

        def _draw_header(self):
            s = self.s
            x, y = 14 * s, 12 * s
            label = {"cards": "環繞版面", "band": "橫帶版面"}.get(self.layout_kind, "陣列版面")
            if self.agent_view:
                text = f"Agent｜{self.mode}｜AI 團隊 {len(self.agents)} 位"
            else:
                n_ans = len([a for a in self.agents if a.get('enabled', True)])
                hub_txt = "＋主持" if self.hub and self.mode in (MODE_SYNTH, MODE_REVIEW, MODE_PLAN) else ""
                text = f"{self.mode}｜{n_ans} 位回答{hub_txt}｜{label}"
            tw = self.f["title"].measure(text)
            self._rrect(x, y, x + tw + 26 * s, y + 28 * s, 14 * s, fill=self.t["surface"], outline=self.t["border"])
            self.create_text(x + 13 * s, y + 14 * s, text=text, anchor="w", fill=self.t["text"], font=self.f["title"])
            y2 = y + 34 * s
            self.create_oval(x + 4 * s, y2 + 6 * s, x + 12 * s, y2 + 14 * s,
                             fill=self.t["accent"] if self.running else self.t["line"], outline="", tags=("phase_dot",))
            self.create_text(x + 18 * s, y2 + 10 * s, text=self.phase, anchor="w", fill=self.t["muted"],
                             font=self.f["body"], tags=("phase_text",))

        def _line(self, points, pid, base_width=1.4):
            active = self.states.get(pid) in ACTIVE_STATES
            flat = [v for p in points for v in p]
            self.create_line(*flat, fill=self._color(pid) if active else self.t["line"],
                             width=max(1, (2 if active else base_width) * self.s), dash=(6, 5),
                             tags=("line", f"line:{pid}"))

        # ── 1～8 位：環繞版面 ──
        def _draw_cards_layout(self, w, h):
            s = self.s
            cx, cy = w / 2, h / 2 + 6 * s
            card_w = 196 * s
            rx = max(150 * s, w / 2 - card_w - 70 * s)
            ry = max(105 * s, h / 2 - 100 * s)
            n = len(self.agents)
            right = (n + 1) // 2

            def angles(k):
                if k <= 0:
                    return []
                if k == 1:
                    return [0.0]
                span = min(100.0, 34.0 * (k - 1))
                return [-span / 2 + span * i / (k - 1) for i in range(k)]

            places = [(cx + rx * math.cos(math.radians(a)), cy + ry * math.sin(math.radians(a)), "right")
                      for a in angles(right)]
            places += [(cx - rx * math.cos(math.radians(a)), cy + ry * math.sin(math.radians(a)), "left")
                       for a in angles(n - right)]
            hub_pt = (cx, cy + 10 * s)
            self.pos[HUB_ID] = hub_pt
            for agent, (x, y, _side) in zip(self.agents, places):
                pid = agent["id"]
                self.pos[pid] = (x, y + 10 * s)
                self.paths[pid] = [hub_pt, (x, y + 10 * s)]
                self._line(self.paths[pid], pid)
            top_y = max(52 * s, cy - ry - 20 * s)
            bottom_y = min(h - 48 * s, cy + ry + 34 * s)
            if self.mode != MODE_PARALLEL:
                self.create_line(cx, cy - 70 * s, cx, top_y + 28 * s, fill=self.t["line"], dash=(4, 4))
                self.create_line(cx, cy + 60 * s, cx, bottom_y - 30 * s, fill=self.t["line"], dash=(4, 4))
            self._draw_context(cx, top_y)
            self._draw_hub(cx, cy, 1.25)
            for agent, (x, y, side) in zip(self.agents, places):
                self._draw_agent_card(agent, x, y, side, card_w, w)
            self._draw_final(cx, bottom_y, 120 * s)

        def _draw_agent_card(self, agent, x, y, side, card_w, canvas_w):
            s = self.s
            pid = agent["id"]
            tags = ("node", f"node:{pid}")
            color, light = self._color(pid), self._light(pid)
            state = self.states.get(pid, "idle")
            if state in ACTIVE_STATES:
                self.create_oval(x - 58 * s, y + 10 * s, x + 58 * s, y + 56 * s, outline=color, width=max(1, 2 * s),
                                 tags=tags + (f"glow:{pid}",))
            self._robot(pid, x, y - 6 * s, 0.9, color, light, tags, agent.get("role"))
            self._badge(x, y + 34 * s, ROLES.get(agent.get("role"), ROLES[DEFAULT_ROLE])["icon"], color, tags, 0.95)
            self._rank_badge(pid, x - 34 * s, y - 40 * s, tags)
            card_h = 84 * s
            x1 = min(x + 54 * s, canvas_w - card_w - 8 * s) if side == "right" else max(x - 54 * s - card_w, 8 * s)
            x2 = x1 + card_w
            y1 = y - card_h / 2 - 6 * s
            selected = self.selected == pid
            self._card(x1, y1, x2, y1 + card_h, tags, outline=color if selected else None,
                       width=max(1, (2 if selected else 1) * s))
            self.create_rectangle(x1 + 10 * s, y1 + 12 * s, x1 + 13 * s, y1 + 26 * s, fill=color, outline="", tags=tags)
            chip_w = self._chip(pid, x2 - 8 * s, y1 + 19 * s, card_w * 0.5, tags)
            title = self._fit(agent.get("name") or "未命名", self.f["title"], card_w - chip_w - 34 * s)
            self.create_text(x1 + 19 * s, y1 + 19 * s, text=title, anchor="w", fill=self.t["text"],
                             font=self.f["title"], tags=tags)
            meta = agent.get("meta") or f"{agent.get('role') or DEFAULT_ROLE}｜{short_model(agent.get('model')) or '未設定模型'}"
            self.create_text(x1 + 12 * s, y1 + 38 * s, text=self._fit(meta, self.f["small"], card_w - 24 * s),
                             anchor="w", fill=self.t["muted"], font=self.f["small"], tags=tags)
            preview = self.previews.get(pid) or ("（停用中，右鍵可啟用）" if state == "disabled" else "點一下查看回覆")
            self.create_text(x1 + 12 * s, y1 + 50 * s, text=self._fit(preview, self.f["small"], card_w - 24 * s, 2),
                             anchor="nw", width=card_w - 24 * s,
                             fill=self.t["text"] if self.previews.get(pid) else self.t["muted"],
                             font=self.f["small"], tags=tags + (f"preview:{pid}",))
            self.card_geom[pid] = (card_w - 24 * s, 2, card_w * 0.5)
            self._bind_node(pid)

        # ── 橫帶版面：主持 AI／Agent 在中央，兩側以機器人小卡排成 1～3 列 ──
        HUB_BAND_W = 250

        def _band_dims(self, rows):
            n = len(self.agents)
            left = n // 2
            right = n - left
            cols = max(1, math.ceil(max(left, right) / rows))
            need_w = self.HUB_BAND_W + 2 * cols * self.TILE_W + 30
            need_h = max(rows * self.TILE_H, 290) + 66        # 中央欄要放共享脈絡、主持 AI、最終成果
            return cols, need_w, need_h

        def _band_fit(self, w, h):
            best, best_rows = 0.0, 1
            if not self.agents:
                return 0.0, 1
            for rows in (1, 2, 3):
                if rows > 1 and math.ceil(len(self.agents) / 2) < rows:
                    break
                _cols, need_w, need_h = self._band_dims(rows)
                fit = min(1.0, w / (need_w * self.base), h / (need_h * self.base))
                if fit > best + 0.02:
                    best, best_rows = fit, rows
            return best, best_rows

        def _draw_band_layout(self, w, h):
            s = self.s
            rows = self.band_rows
            cols, need_w, need_h = self._band_dims(rows)
            cx = w / 2
            cy = 36 * s + (h - 36 * s) / 2 - 8 * s
            hub_pt = (cx, cy + 10 * s)
            self.pos[HUB_ID] = hub_pt
            n = len(self.agents)
            left_n = n // 2
            right = self.agents[:n - left_n]
            left = self.agents[n - left_n:]
            places = []
            for side, group in ((1, right), (-1, left)):
                for i, agent in enumerate(group):
                    col, row = divmod(i, rows)
                    in_col = min(rows, len(group) - col * rows)
                    x = cx + side * (self.HUB_BAND_W / 2 + (col + 0.5) * self.TILE_W) * s
                    top = cy - in_col * self.TILE_H * s / 2 + row * self.TILE_H * s
                    places.append((agent, x, top, side))
            for agent, x, top, side in places:
                pid = agent["id"]
                anchor = (x - side * (self.TILE_W - 12) * s / 2, top + 6 * s + (self.TILE_H - 12) * s / 2)
                self.paths[pid] = [hub_pt, anchor]
                self.pos[pid] = anchor
                self._line(self.paths[pid], pid)
            self._draw_hub(cx, cy - 6 * s, 0.85)
            if h > 260 * s:
                self._draw_context(cx - 26 * s, max(36 * s, cy - 118 * s))
            self._draw_final(cx, min(h - 36 * s, cy + 108 * s), 86 * s)
            for agent, x, top, _side in places:
                self._draw_agent_tile(agent, x, top)

        # ── 9 位以上：陣列版面 ──
        TILE_W, TILE_H, TOP_BAND = 168, 150, 200

        def _grid_dims(self, w, s):
            cols = max(1, int((w - 24 * s) // (self.TILE_W * s)))
            cols = min(cols, max(1, len(self.agents)))
            rows = math.ceil(len(self.agents) / cols) if self.agents else 0
            return cols, rows

        def _grid_fit(self, w, h):
            fit = min(1.0, w / (1000 * self.base))
            while fit > 0.42:
                s = self.base * fit
                cols, rows = self._grid_dims(w, s)
                if (self.TOP_BAND + rows * self.TILE_H + 16) * s <= h:
                    break
                fit *= 0.95
            return fit

        def _draw_grid_layout(self, w, h):
            s = self.s
            cx = w / 2
            hub_y = 92 * s
            cols, rows = self._grid_dims(w, s)
            grid_w = cols * self.TILE_W * s
            gx = (w - grid_w) / 2
            gy = self.TOP_BAND * s
            bus_y = gy - 18 * s
            hub_pt = (cx, hub_y + 52 * s)
            self.pos[HUB_ID] = (cx, hub_y)
            places = []
            for i, agent in enumerate(self.agents):
                r, c = divmod(i, cols)
                in_row = min(cols, len(self.agents) - r * cols)
                offset = (cols - in_row) * self.TILE_W * s / 2      # 最後一列置中
                x = gx + offset + (c + 0.5) * self.TILE_W * s
                y = gy + r * self.TILE_H * s
                places.append((x, y))
            # 匯流線：主持 AI → 水平匯流排 → 各列
            if places:
                xs = [p[0] for p in places]
                self.create_line(cx, hub_pt[1], cx, bus_y, fill=self.t["line"], width=max(1, 1.4 * s), dash=(6, 5))
                self.create_line(min(xs + [cx]), bus_y, max(xs + [cx]), bus_y, fill=self.t["line"],
                                 width=max(1, 1.4 * s), dash=(6, 5))
            for agent, (x, y) in zip(self.agents, places):
                pid = agent["id"]
                top = (x, y + 4 * s)
                self.paths[pid] = [hub_pt, (cx, bus_y), (x, bus_y), top]
                self.pos[pid] = (x, y + 50 * s)
                self.anchor[pid] = top
                self._line([(x, bus_y), top], pid)
            self._draw_hub(cx, hub_y, 0.95)
            self._draw_context(max(70 * s, cx - 250 * s), 60 * s)
            self._draw_final(min(w - 130 * s, cx + 270 * s), 96 * s, 112 * s)
            for agent, (x, y) in zip(self.agents, places):
                self._draw_agent_tile(agent, x, y)

        def _draw_agent_tile(self, agent, x, y):
            s = self.s
            pid = agent["id"]
            tags = ("node", f"node:{pid}")
            color, light = self._color(pid), self._light(pid)
            tw, th = (self.TILE_W - 12) * s, (self.TILE_H - 12) * s
            x1, y1 = x - tw / 2, y + 6 * s
            selected = self.selected == pid
            self._card(x1, y1, x1 + tw, y1 + th, tags, outline=color if selected else None,
                       width=max(1, (2 if selected else 1) * s), r=14)
            state = self.states.get(pid, "idle")
            if state in ACTIVE_STATES:
                self._rrect(x1 - 3 * s, y1 - 3 * s, x1 + tw + 3 * s, y1 + th + 3 * s, 16 * s, fill="", outline=color,
                            width=max(1, 2 * s), tags=tags + (f"glow:{pid}",))
            self._robot(pid, x, y1 + 46 * s, 0.62, color, light, tags, agent.get("role"))
            self._badge(x + 31 * s, y1 + 73 * s, ROLES.get(agent.get("role"), ROLES[DEFAULT_ROLE])["icon"], color,
                        tags, 0.75)
            self._rank_badge(pid, x1 + 18 * s, y1 + 18 * s, tags)
            self.create_text(x, y1 + 92 * s, text=self._fit(agent.get("name") or "未命名", self.f["title"], tw - 16 * s),
                             fill=self.t["text"], font=self.f["title"], tags=tags)
            self.create_text(x, y1 + 108 * s, text=self._fit(agent.get("meta") or f"{agent.get('role') or DEFAULT_ROLE}・{short_model(agent.get('model')) or '未設定模型'}", self.f["small"],
                                                             tw - 16 * s),
                             fill=self.t["muted"], font=self.f["small"], tags=tags)
            text, scolor = self.t.status(state)
            detail = self.details.get(pid) or ""
            label = self._fit(text + (f" {detail}" if detail else ""), self.f["small"], tw - 34 * s)
            cw = self.f["small"].measure(label) + 20 * s
            self._chip(pid, x + cw / 2, y1 + th - 14 * s, tw - 34 * s, tags)
            self.card_geom[pid] = (None, 0, tw - 34 * s)
            self._bind_node(pid)

        # ── 共用節點 ──
        def _draw_hub(self, cx, cy, k):
            s = self.s * k
            tags = ("node", f"node:{HUB_ID}")
            uses_hub = self.agent_view or self.mode in (MODE_SYNTH, MODE_REVIEW, MODE_PLAN)
            color = self.t["hub"] if uses_hub else mix(self.t["hub"], self.t["canvas"], 0.45)
            light = self.t["hub_light"]
            self.create_oval(cx - 90 * s, cy - 16 * s, cx + 90 * s, cy + 53 * s,
                             fill=mix(light, self.t["canvas"], 0.5), outline="", tags=tags)
            self.create_oval(cx - 77 * s, cy - 6 * s, cx + 77 * s, cy + 45 * s, fill=light,
                             outline=mix(color, self.t["canvas"], 0.35), width=max(1, 2 * self.s), tags=tags)
            self.hub_arc = self.create_arc(cx - 77 * s, cy - 6 * s, cx + 77 * s, cy + 45 * s, start=self.arc_angle,
                                           extent=70, style="arc", outline=color, width=max(2, 3 * self.s), tags=tags)
            self.create_oval(cx - 56 * s, cy + 3 * s, cx + 56 * s, cy + 35 * s,
                             fill=mix(light, self.t["surface"], 0.55), outline="", tags=tags)
            if self.selected == HUB_ID:
                self.create_oval(cx - 82 * s, cy - 10 * s, cx + 82 * s, cy + 49 * s, outline=self.t["accent"],
                                 width=max(2, 2.5 * self.s), tags=tags)
            self._robot(HUB_ID, cx, cy - 16 * s, k, color, light, tags, "Agent" if self.agent_view else "主持")
            name = "主持 AI" + (f"：{self.hub.get('name')}" if self.hub and uses_hub else "（此模式不需要）")
            if self.agent_view:
                name = f"Agent：{self.hub.get('name')}" if self.hub else "Agent（尚未選擇模型）"
            self.create_text(cx, cy + 58 * s, text=self._fit(name, self.f["hub"], 260 * self.s), fill=self.t["text"],
                             font=self.f["hub"], tags=tags)
            self.create_text(cx, cy + 75 * s, text=self._hub_status_text(), fill=self.t.status(self.states.get(HUB_ID, "idle"))[1],
                             font=self.f["small"], tags=tags + ("hub_status",))
            self._bind_node(HUB_ID)

        def _hub_status_text(self):
            uses_hub = self.agent_view or self.mode in (MODE_SYNTH, MODE_REVIEW, MODE_PLAN)
            status = self.t.status(self.states.get(HUB_ID, "idle"))[0]
            detail = self.details.get(HUB_ID) or ""
            model = self.hub.get("model", "") if self.hub and uses_hub else ""
            return "｜".join(x for x in (self._fit(model, self.f["small"], 150 * self.s),
                                         status + (f" {detail}" if detail else "")) if x)

        def _draw_context(self, cx, y):
            s = self.s
            tags = ("node", f"node:{CONTEXT_ID}")
            color = mix(self.t["accent"], self.t["canvas"], 0.35 if self.mode != MODE_PARALLEL else 0.65)
            fill = mix(self.t["accent"], self.t["surface"], 0.9)
            for i in range(3):
                top = y + i * 9 * s
                self.create_rectangle(cx - 22 * s, top + 4 * s, cx + 22 * s, top + 12 * s, fill=fill, outline="",
                                      tags=tags)
                self.create_line(cx - 22 * s, top + 4 * s, cx - 22 * s, top + 12 * s, fill=color, tags=tags)
                self.create_line(cx + 22 * s, top + 4 * s, cx + 22 * s, top + 12 * s, fill=color, tags=tags)
                self.create_arc(cx - 22 * s, top + 6 * s, cx + 22 * s, top + 18 * s, start=180, extent=180,
                                style="arc", outline=color, tags=tags)
            self.create_oval(cx - 22 * s, y - 2 * s, cx + 22 * s, y + 10 * s, fill=self.t["surface"], outline=color,
                             tags=tags)
            self.create_text(cx + 32 * s, y + 14 * s, text=self.round_text, anchor="w", fill=self.t["muted"],
                             font=self.f["small"], tags=tags + ("context_text",))
            self._bind_node(CONTEXT_ID)

        def _draw_final(self, cx, y, half_w):
            s = self.s
            tags = ("node", f"node:{FINAL_ID}")
            h2 = 30 * s
            selected = self.selected == FINAL_ID
            self._card(cx - half_w, y - h2, cx + half_w, y + h2, tags,
                       outline=self.t["accent"] if selected else None, width=max(1, (2 if selected else 1) * s), r=14)
            self._badge(cx - half_w + 24 * s, y, "doc", self.t["accent"], tags, 1.0)
            label = {MODE_PARALLEL: "各家回答（未彙整）", MODE_RELAY: "最終成果（最後一棒）"}.get(self.mode, "最終成果")
            self.create_text(cx - half_w + 44 * s, y - 10 * s, text=label, anchor="w", fill=self.t["text"],
                             font=self.f["title"], tags=tags)
            self.final_geom = 2 * half_w - 56 * s
            self.create_text(cx - half_w + 44 * s, y + 10 * s, anchor="w", fill=self.t["muted"], font=self.f["small"],
                             text=self._fit(self.final_preview or "完成後點這裡查看", self.f["small"], self.final_geom),
                             tags=tags + ("final_text",))
            self._bind_node(FINAL_ID)

        def _rank_badge(self, pid, x, y, tags):
            """互評綜合名次徽章（第 1 名金色、第 2 名銀色、第 3 名銅色）。"""
            if pid not in self.ranks:
                return
            order = sorted(self.ranks, key=lambda p: self.ranks[p])
            place = order.index(pid) + 1
            color = {1: "#E5A823", 2: "#9AA5B4", 3: "#C27A45"}.get(place, self.t["muted"])
            r = 11 * self.s
            self.create_oval(x - r, y - r, x + r, y + r, fill=color, outline=self.t["surface"], width=max(1, 2 * self.s),
                             tags=tags)
            self.create_text(x, y, text=f"#{place}", fill="#FFFFFF", font=self.f["small"], tags=tags)

        def set_ranks(self, ranks):
            self.ranks = dict(ranks or {})
            self._schedule_redraw()

        def _bind_node(self, pid):
            tag = f"node:{pid}"
            self.tag_bind(tag, "<Button-1>", lambda _e, p=pid: self.cb.get("select", lambda _p: None)(p))
            self.tag_bind(tag, "<Double-Button-1>", lambda _e, p=pid: self.cb.get("open", lambda _p: None)(p))
            self.tag_bind(tag, "<Button-3>", lambda e, p=pid: self.cb.get("menu", lambda _p, _e: None)(p, e))
            self.tag_bind(tag, "<Enter>", lambda e, p=pid: (self.configure(cursor="hand2"), self._show_tip(p, e)))
            self.tag_bind(tag, "<Motion>", lambda e, p=pid: self._move_tip(e))
            self.tag_bind(tag, "<Leave>", lambda _e: (self.configure(cursor=""), self._hide_tip()))

        # ───────────── 提示框（滑鼠移上去顯示完整資訊） ─────────────
        def _tip_lines(self, pid):
            if pid in (FINAL_ID, CONTEXT_ID):
                return ["點一下查看" + ("最終成果" if pid == FINAL_ID else "共享脈絡")]
            if pid == HUB_ID:
                if not self.hub:
                    return ["主持 AI：未設定"]
                return [f"主持 AI：{self.hub.get('name')}", f"模型：{self.hub.get('model')}",
                        "狀態：" + self.t.status(self.states.get(HUB_ID, "idle"))[0],
                        "雙擊編輯設定、右鍵更多操作"]
            a = self._agent(pid)
            if not a:
                return []
            lines = [a.get("name") or "未命名", f"角色：{a.get('role') or DEFAULT_ROLE}",
                     f"模型：{a.get('model') or '未設定'}"]
            status = self.t.status(self.states.get(pid, "idle"))[0]
            detail = self.details.get(pid)
            lines.append(f"狀態：{status}" + (f" {detail}" if detail else ""))
            if pid in self.ranks:
                lines.append(f"互評平均名次：{self.ranks[pid]:.1f}")
            lines.append("點一下看回覆・雙擊編輯・右鍵更多")
            return lines

        def _show_tip(self, pid, event):
            self._hide_tip()
            lines = self._tip_lines(pid)
            if not lines:
                return
            self.tip_pid = pid
            s = self.base
            text = "\n".join(lines)
            item = self.create_text(0, 0, text=text, anchor="nw", fill=self.t["text"], font=self.f["body"],
                                    tags=("tip", "tip_text"))
            x1, y1, x2, y2 = self.bbox(item)
            pad = 8 * s
            self._rrect(0, 0, x2 - x1 + 2 * pad, y2 - y1 + 2 * pad, 8 * s, fill=self.t["surface"],
                        outline=self.t["accent"], tags=("tip", "tip_bg"))
            self.tag_raise("tip_text")
            self.tip_size = (x2 - x1 + 2 * pad, y2 - y1 + 2 * pad, pad)
            self._move_tip(event)

        def _move_tip(self, event):
            if not self.tip_pid or not self.find_withtag("tip"):
                return
            w, h, pad = self.tip_size
            x = event.x + 16
            y = event.y + 16
            if x + w > self.winfo_width() - 4:
                x = event.x - w - 12
            if y + h > self.winfo_height() - 4:
                y = event.y - h - 12
            bg = self.find_withtag("tip_bg")
            if bg:
                bx1, by1, _bx2, _by2 = self.bbox(bg[0])
                self.move("tip_bg", x - bx1, y - by1)
            self.coords("tip_text", x + pad, y + pad)
            self.tag_raise("tip")

        def _hide_tip(self):
            self.tip_pid = None
            self.delete("tip")

        # ───────────── 局部更新 ─────────────
        def _update_node(self, pid):
            if pid == HUB_ID:
                self.itemconfigure("hub_status", text=self._hub_status_text(),
                                   fill=self.t.status(self.states.get(HUB_ID, "idle"))[1])
                return
            if pid not in self.pos:
                return
            state = self.states.get(pid, "idle")
            if (state in ACTIVE_STATES) != bool(self.find_withtag(f"glow:{pid}")):
                self._schedule_redraw()
                return
            color = self._color(pid)
            active = state in ACTIVE_STATES
            self.itemconfigure(f"line:{pid}", fill=color if active else self.t["line"],
                               width=max(1, (2 if active else 1.4) * self.s))
            text, scolor = self.t.status(state)
            detail = self.details.get(pid) or ""
            geom = self.card_geom.get(pid)
            label = text + (f" {detail}" if detail else "")
            old = self.itemcget(f"chip:{pid}", "text") if self.find_withtag(f"chip:{pid}") else ""
            if geom and self.f["small"].measure(self._fit(label, self.f["small"], geom[2])) > self.f["small"].measure(old) + 2:
                self._schedule_redraw()      # 膠囊變寬時重畫，讓標題讓出空間
            if geom:
                label = self._fit(label, self.f["small"], geom[2])
            self.itemconfigure(f"chip:{pid}", text=label, fill=scolor)
            self.itemconfigure(f"chipdot:{pid}", fill=scolor)
            self.itemconfigure(f"chipbg:{pid}", fill=mix(scolor, self.t["surface"], 0.85))
            if geom and geom[0] and self.previews.get(pid):
                self.itemconfigure(f"preview:{pid}", text=self._fit(self.previews[pid], self.f["small"], geom[0], geom[1]),
                                   fill=self.t["text"])

        # ───────────── 動畫 ─────────────
        def _link_path(self, src, dst, kind):
            if src == HUB_ID:
                return self.paths.get(dst)
            if kind == "synth" or dst == HUB_ID:
                p = self.paths.get(src)
                return list(reversed(p)) if p else None
            a, b = self.paths.get(src), self.paths.get(dst)
            if not a or not b:
                return None
            if self.layout_kind == "grid":
                return list(reversed(a))[:-1] + b[1:]
            hub = self.pos[HUB_ID]
            pa, pb = a[-1], b[-1]
            mid = ((pa[0] + pb[0]) / 2, (pa[1] + pb[1]) / 2)
            ctrl = (mid[0] + (hub[0] - mid[0]) * 0.55, mid[1] + (hub[1] - mid[1]) * 0.55)
            return _bezier(pa, ctrl, pb)

        def _spawn(self, points, color, size=4, speed=0.035):
            if len(points) < 2:
                return
            lengths = [math.dist(points[i], points[i + 1]) for i in range(len(points) - 1)]
            total = sum(lengths) or 1
            r = size * self.s
            x, y = points[0]
            item = self.create_oval(x - r, y - r, x + r, y + r, fill=color, outline=self.t["surface"], width=1)
            self.packets.append({"item": item, "pts": points, "len": lengths, "total": total, "t": 0.0,
                                 "speed": speed * min(2.0, max(0.6, 500 * self.s / total)), "r": r})

        def _at(self, p):
            d = p["t"] * p["total"]
            for i, seg in enumerate(p["len"]):
                if d <= seg or i == len(p["len"]) - 1:
                    f = 0 if seg == 0 else min(1.0, d / seg)
                    (x1, y1), (x2, y2) = p["pts"][i], p["pts"][i + 1]
                    return x1 + (x2 - x1) * f, y1 + (y2 - y1) * f
                d -= seg
            return p["pts"][-1]

        def _animate(self):
            try:
                self.frame += 1
                if self.t.animate and self.running:
                    if self.hub_arc:
                        self.arc_angle = (self.arc_angle - 6) % 360
                        self.itemconfigure(self.hub_arc, start=self.arc_angle)
                    for a in self.agents:
                        pid = a["id"]
                        state = self.states.get(pid)
                        path = self.paths.get(pid)
                        if state not in ACTIVE_STATES or not path:
                            continue
                        if self.frame >= self.flow_timer.get(pid, 0):
                            self.flow_timer[pid] = self.frame + (10 if state == "generating" else 16)
                            self._spawn(list(reversed(path)) if state == "generating" else path, self._color(pid))
                    if self.states.get(HUB_ID) in ACTIVE_STATES and self.frame % 14 == 0:
                        for a in self.agents:
                            if a.get("enabled", True) and self.paths.get(a["id"]):
                                self._spawn(list(reversed(self.paths[a["id"]])), self.t["hub"], size=3)
                    width = max(1, (1.5 + abs(math.sin(self.frame / 6))) * self.s)
                    for a in self.agents:
                        self.itemconfigure(f"glow:{a['id']}", width=width)
                alive = []
                for p in self.packets:
                    p["t"] += p["speed"]
                    if p["t"] >= 1:
                        self.delete(p["item"])
                        continue
                    x, y = self._at(p)
                    r = p["r"]
                    self.coords(p["item"], x - r, y - r, x + r, y + r)
                    alive.append(p)
                self.packets = alive
                if self.t.animate and self.sprites and self.frame % 2 == 0:      # 動態角色：每 80 毫秒換一格
                    step = self.frame // 2
                    for item, frames, phase in self.sprites.values():
                        self.itemconfigure(item, image=frames[(step + phase) % ROBOT_SPRITE_FRAMES])
                if self.t.animate and self.frame % 25 == 0 and self.eyes:
                    pid = random.choice(list(self.eyes))
                    for item, (x1, y1, x2, y2) in self.eyes[pid]:
                        mid = (y1 + y2) / 2
                        self.coords(item, x1, mid - 1, x2, mid + 1)
                    self.after(130, lambda p=pid: self._open_eyes(p))
            except tk.TclError:
                return
            self.after(40, self._animate)

        def _open_eyes(self, pid):
            try:
                for item, coords in self.eyes.get(pid, []):
                    self.coords(item, *coords)
            except tk.TclError:
                pass

    return TopologyView


# ═════════════════════════ 7. 主視窗（對話為主的版面） ═════════════════════════
# 版面參考 opencode／Claude／ChatGPT／llm-council 等：左邊是對話清單，中間是對話串，
# 每次工具呼叫是一張可展開的小卡、危險動作會跳出核准卡；右邊是任務清單與變更的檔案。
log_app = logging.getLogger("ai_collab.app")
STATUS_FROM_RESULT = {"done": "done", "stopped": "stopped", "error": "error", "timeout": "timeout", "empty": "empty"}

def enable_high_dpi():
    if sys.platform != "win32":
        return
    try:
        import ctypes
        ctypes.windll.shcore.SetProcessDpiAwareness(1)
    except Exception:
        pass


def open_path(path, parent=None):
    """用系統預設的程式開啟檔案或資料夾。回傳是否成功。
    v6.18.1：先確認檔案存在、不是空的；Windows 沒有替這種副檔名設定預設程式時（os.startfile 會失敗），
    改在檔案總管選取它，並說明怎麼設定，不再只丟出「無法開啟」。"""
    opts = {"parent": parent} if parent is not None else {}
    if not path or not os.path.exists(path):
        messagebox.showerror(APP_NAME, f"找不到：{path or '（沒有路徑）'}\n可能已經被移動或刪除。", **opts)
        return False
    if os.path.isfile(path) and os.path.getsize(path) == 0:
        messagebox.showerror(APP_NAME, f"這個檔案是空的（0 bytes），通常表示生成沒有成功：\n{path}", **opts)
        return False
    try:
        if sys.platform == "win32":
            os.startfile(os.path.normpath(path))
        else:
            import subprocess
            subprocess.Popen(["open" if sys.platform == "darwin" else "xdg-open", path])
        return True
    except Exception as exc:
        if sys.platform == "win32" and os.path.isfile(path) and reveal_in_folder(path):
            ext = os.path.splitext(path)[1] or "這種"
            messagebox.showinfo(APP_NAME, f"這台電腦還沒有設定用什麼程式開啟 {ext} 檔（{exc}）。\n\n"
                                          "已經在檔案總管選取這個檔案：在它上面按右鍵 →「開啟檔案」→「選擇其他應用程式」，"
                                          "選「媒體播放器」「相片」等，並勾選「一律使用此應用程式」。", **opts)
            return False
        messagebox.showerror(APP_NAME, f"無法開啟：{path}\n{exc}", **opts)
        return False


def reveal_in_folder(path):
    """在檔案總管（Finder）裡選取這個檔案；不支援選取時開啟所在資料夾。"""
    try:
        import subprocess
        if sys.platform == "win32":
            subprocess.Popen(["explorer", "/select," + os.path.normpath(path)])
        elif sys.platform == "darwin":
            subprocess.Popen(["open", "-R", path])
        else:
            subprocess.Popen(["xdg-open", os.path.dirname(path) or "."])
        return True
    except Exception:
        return False


def _make_app_class():
    TopologyView = _make_topology_class()

    class ScrollFrame(ttk.Frame):
        """可垂直捲動的容器（內容放在 self.inner）。"""

        def __init__(self, app, master):
            super().__init__(master, style="Surface.TFrame")
            self.canvas = tk.Canvas(self, highlightthickness=0, bd=0)
            app._register_tk(self.canvas, "surface")
            self.bar = ttk.Scrollbar(self, orient="vertical", command=self.canvas.yview)
            self.inner = ttk.Frame(self.canvas, style="Surface.TFrame")
            self.inner.bind("<Configure>", lambda _e: self.canvas.configure(scrollregion=self.canvas.bbox("all")))
            self.window = self.canvas.create_window((0, 0), window=self.inner, anchor="nw")
            self.canvas.bind("<Configure>", lambda e: self.canvas.itemconfigure(self.window, width=e.width))
            self.canvas.configure(yscrollcommand=self.bar.set)
            self.canvas.pack(side="left", fill="both", expand=True)
            self.bar.pack(side="right", fill="y")
            self.canvas._scroll_frame = self.inner._scroll_frame = self

    class EndpointEditor:
        """「端點」分頁中的一張 AI 設定卡。"""

        def __init__(self, app, parent, service, index):
            self.app = app
            self.service = service
            self.frame = ttk.Frame(parent, style="Card.TFrame", padding=(12, 10))
            self.frame.pack(fill="x", pady=(0, 10), padx=(0, 6))
            f = self.frame
            f.columnconfigure(1, weight=3)
            f.columnconfigure(3, weight=1)
            self.vars = {k: tk.StringVar(value=service.get(k, "")) for k in
                         ("name", "role", "url", "model", "credential", "temperature", "max_tokens", "task")}
            self.reasoning_var = tk.StringVar(value=REASONING_LABELS.get(service.get("reasoning", ""), "模型預設"))
            if not self.vars["credential"].get():
                self.vars["credential"].set(service.get("credential_env", ""))
            self.enabled = tk.BooleanVar(value=service.get("enabled", True))

            # 第 1 列：色點、編號、名稱、參與
            head = ttk.Frame(f, style="Surface.TFrame")
            head.grid(row=0, column=0, columnspan=4, sticky="ew")
            self.dot = tk.Canvas(head, width=16, height=16, highlightthickness=0)
            app._register_tk(self.dot, "surface")
            self.dot.pack(side="left", padx=(0, 6))
            ttk.Label(head, text=f"#{index + 1}", style="Muted.TLabel").pack(side="left", padx=(0, 6))
            ttk.Entry(head, textvariable=self.vars["name"], width=8).pack(side="left", fill="x", expand=True)
            ttk.Checkbutton(head, text="參與", variable=self.enabled, command=self._changed).pack(side="left", padx=(8, 0))
            # 第 2 列：操作按鈕
            tools = ttk.Frame(f, style="Surface.TFrame")
            tools.grid(row=1, column=0, columnspan=4, sticky="ew", pady=(6, 6))
            ttk.Button(tools, text="選擇模型…", style="Ghost.TButton",
                       command=lambda: app.open_model_picker(self)).pack(side="left")
            self.test_button = ttk.Button(tools, text="測試", style="Ghost.TButton",
                                          command=lambda: app.test_service(self.service))
            self.test_button.pack(side="left", padx=(4, 0))
            self.remove_button = ttk.Button(tools, text="移除", style="Danger.TButton",
                                            command=lambda: app.remove_service(service))
            self.remove_button.pack(side="right")
            ttk.Button(tools, text="↓", width=2, style="Ghost.TButton",
                       command=lambda: app.move_service(service, 1)).pack(side="right", padx=(0, 6))
            ttk.Button(tools, text="↑", width=2, style="Ghost.TButton",
                       command=lambda: app.move_service(service, -1)).pack(side="right", padx=(0, 2))

            def label(row, col, text):
                ttk.Label(f, text=text, style="Muted.TLabel").grid(row=row, column=col, sticky="w", padx=(0, 6), pady=3)

            label(2, 0, "角色")
            role = ttk.Combobox(f, textvariable=self.vars["role"], values=list(ROLES), state="readonly", width=8)
            role.grid(row=2, column=1, sticky="ew", pady=3)
            role.bind("<<ComboboxSelected>>", lambda _e: self._changed())
            label(2, 2, "  溫度")
            ttk.Entry(f, textvariable=self.vars["temperature"], width=4).grid(row=2, column=3, sticky="ew", pady=3)
            label(3, 0, "網址")
            ttk.Entry(f, textvariable=self.vars["url"], width=10).grid(row=3, column=1, columnspan=3, sticky="ew", pady=3)
            label(4, 0, "模型")
            self.model_combo = ttk.Combobox(f, textvariable=self.vars["model"], width=10)
            self.model_combo.grid(row=4, column=1, columnspan=3, sticky="ew", pady=3)
            label(5, 0, "金鑰")
            self.key_entry = ttk.Entry(f, textvariable=self.vars["credential"], width=8)
            self.key_entry.grid(row=5, column=1, sticky="ew", pady=3)
            label(5, 2, "  上限")
            ttk.Entry(f, textvariable=self.vars["max_tokens"], width=4).grid(row=5, column=3, sticky="ew", pady=3)

            label(6, 0, "工作")
            ttk.Entry(f, textvariable=self.vars["task"], width=10).grid(row=6, column=1, columnspan=3, sticky="ew", pady=3)
            label(7, 0, "思考")
            rc = ttk.Combobox(f, textvariable=self.reasoning_var, values=list(REASONING_LABELS.values()), state="readonly", width=10)
            rc.grid(row=7, column=1, columnspan=3, sticky="ew", pady=3)
            rc.bind("<<ComboboxSelected>>", lambda _e: self._changed())
            self.reason_hint = ttk.Label(f, text="", style="Muted.TLabel", wraplength=300)
            self.reason_hint.grid(row=8, column=0, columnspan=4, sticky="w")
            # v6.7.0：本機大模型（Ollama）——上下文長度與保持載入；只有網址是 Ollama 時顯示
            self.ctx_var = tk.StringVar(value=next((lab for lab, v in OLLAMA_CTX_CHOICES if v == service.get("num_ctx", "")),
                                                   OLLAMA_CTX_CHOICES[0][0]))
            self.keep_var = tk.StringVar(value=next((lab for lab, v in OLLAMA_KEEP_CHOICES if v == service.get("keep_alive", "")),
                                                    OLLAMA_KEEP_CHOICES[0][0]))
            self.local_row = ttk.Frame(f, style="Surface.TFrame")
            self.local_row.grid(row=9, column=0, columnspan=4, sticky="ew", pady=3)
            ttk.Label(self.local_row, text="本機上下文", style="Muted.TLabel").pack(side="left", padx=(0, 6))
            cc = ttk.Combobox(self.local_row, textvariable=self.ctx_var, values=[lab for lab, _v in OLLAMA_CTX_CHOICES],
                              state="readonly", width=10)
            cc.pack(side="left")
            ttk.Label(self.local_row, text="  保持載入", style="Muted.TLabel").pack(side="left", padx=(0, 6))
            kc = ttk.Combobox(self.local_row, textvariable=self.keep_var, values=[lab for lab, _v in OLLAMA_KEEP_CHOICES],
                              state="readonly", width=12)
            kc.pack(side="left")
            for combo in (cc, kc):
                combo.bind("<<ComboboxSelected>>", lambda _e: self._changed())
            self.local_hint = ttk.Label(f, text="顯卡放不下的部分 Ollama 會自動放到系統記憶體；上下文越長越吃記憶體。",
                                        style="Muted.TLabel", wraplength=300)
            self.local_hint.grid(row=10, column=0, columnspan=4, sticky="w")
            self.status = ttk.Label(f, text=service.get("_status", ""), style="Muted.TLabel", wraplength=300)
            self.status.grid(row=11, column=0, columnspan=4, sticky="w", pady=(6, 0))

            def wrap(e):
                for w in (self.status, self.reason_hint, self.local_hint):
                    w.configure(wraplength=max(160, e.width - 30))
            f.bind("<Configure>", wrap)
            cache = app.model_cache.get(service.get("url", "").strip().rstrip("/"))
            if cache:
                self.model_combo.configure(values=cache)
            for var in self.vars.values():
                var.trace_add("write", lambda *_a: self._changed())
            self.key_entry.bind("<KeyRelease>", lambda _e: self.refresh_mask())
            self.refresh_mask()
            self.paint_dot()
            self.refresh_reason_hint()
            self.refresh_local_row()

        def refresh_local_row(self):
            try:
                if ollama_native_base(self.vars["url"].get()):
                    self.local_row.grid()
                    self.local_hint.grid()
                else:
                    self.local_row.grid_remove()
                    self.local_hint.grid_remove()
            except tk.TclError:
                pass

        def refresh_reason_hint(self):
            hint = REASONING_STYLE_HINTS.get(reasoning_style(self.vars["model"].get(), self.vars["url"].get()), "")
            try:
                self.reason_hint.configure(text=hint)
                if hint:
                    self.reason_hint.grid()
                else:
                    self.reason_hint.grid_remove()
            except tk.TclError:
                pass

        def paint_dot(self):
            self.dot.delete("all")
            color = self.app.theme.role_color(self.vars["role"].get()) if self.enabled.get() else self.app.theme["line"]
            self.dot.create_oval(2, 2, 14, 14, fill=color, outline="")

        def refresh_mask(self):
            text = self.vars["credential"].get()
            self.key_entry.configure(show="" if (not text or looks_like_env_name(text)) else "•")

        def set_status(self, text, kind="muted"):
            self.service["_status"] = text
            colors = {"muted": self.app.theme["muted"], "ok": self.app.theme["success"],
                      "bad": self.app.theme["danger"], "warn": self.app.theme["warning"]}
            try:
                self.status.configure(text=text, foreground=colors.get(kind, colors["muted"]))
            except tk.TclError:
                pass

        def _changed(self):
            s = self.service
            old_model, old_url, old_name = s.get("model", ""), s.get("url", ""), s.get("name", "")
            for key, var in self.vars.items():
                s[key] = var.get().strip() if key != "credential" else var.get()
            s["enabled"] = bool(self.enabled.get())
            rev = {v: k for k, v in REASONING_LABELS.items()}
            s["reasoning"] = rev.get(self.reasoning_var.get(), "")
            s["num_ctx"] = dict(OLLAMA_CTX_CHOICES).get(self.ctx_var.get(), "")
            s["keep_alive"] = dict(OLLAMA_KEEP_CHOICES).get(self.keep_var.get(), "")
            self.refresh_local_row()
            self.refresh_reason_hint()
            if not s["credential"].strip() and NVIDIA_HOST in s["url"].lower():
                s["credential"] = DEFAULT_NVIDIA_ENV
            if s.get("model") != old_model or s.get("url") != old_url:
                s.pop("_tested", None)          # 換了模型就要重新測試
                self.set_status("")
                cache = self.app.model_cache.get(s.get("url", "").strip().rstrip("/"))
                if cache:
                    self.model_combo.configure(values=cache)
                    if s.get("model") and s["model"] not in cache:
                        self.set_status("⚠ 這個模型名稱不在服務提供的清單中，請確認拼字或按「選擇模型…」挑選。", "warn")
                # 名稱自動跟著模型：名稱是空白、「AI 數字」或等於舊模型簡稱時，改成新模型簡稱
                if s.get("model") != old_model and (not old_name or re.fullmatch(r"AI\s*\d+", old_name)
                                                    or old_name == short_model(old_model)):
                    new_name = short_model(s.get("model"))
                    if new_name and new_name != old_name:
                        self.vars["name"].set(new_name)
                        return
            self.paint_dot()
            self.app.on_service_changed(s)

    INLINE_MD = re.compile(r"(\*\*[^*\n]+?\*\*|`[^`\n]+`|\[[^\]\n]+\]\([^)\s]+\))")

    class Transcript:
        """對話串：一個 tk.Text，用「區塊」（兩個 mark 夾住的範圍）組成訊息、工具卡、討論區段。

        - 每個區塊有 <id>_s（左黏）與 <id>_e（右黏）兩個 mark，在 _e 插入就會附加到區塊尾端。
        - 可摺疊的區塊用 elide 標籤隱藏內容；巢狀區塊會繼承祖先的摺疊標籤。
        - 回答先以原文串流，完成後再轉成 Markdown 排版（標題、粗體、清單、程式碼框、表格）。
        """

        def __init__(self, app, parent):
            self.app = app
            self.frame = ttk.Frame(parent, style="Chat.TFrame")
            self.text = tk.Text(self.frame, wrap="word", relief="flat", bd=0, padx=34, pady=20, cursor="arrow",
                                highlightthickness=0, spacing1=1, spacing3=1, undo=False, exportselection=True)
            app._register_tk(self.text, "chat")
            bar = ttk.Scrollbar(self.frame, orient="vertical", command=self.text.yview)
            self.text.configure(yscrollcommand=bar.set)
            self.text.pack(side="left", fill="both", expand=True)
            bar.pack(side="right", fill="y")
            self.text.bind("<Key>", self._key)
            self.text.bind("<<Paste>>", lambda _e: "break")
            self.text.bind("<<Copy>>", self._copy)
            self.text.bind("<Button-3>", self._menu)          # v6.6.3：右鍵選單（複製、全選、複製這則訊息）
            self.text.bind("<Configure>", lambda _e: self._resize_windows())
            # 使用者自己捲動時才重新判斷「要不要跟著最新內容捲到底」，寫入文字時不再每次都去算版面
            for seq in ("<MouseWheel>", "<Button-4>", "<Button-5>", "<KeyRelease-Prior>", "<KeyRelease-Next>",
                        "<KeyRelease-Up>", "<KeyRelease-Down>", "<KeyRelease-Home>", "<KeyRelease-End>"):
                self.text.bind(seq, self._user_scrolled, add="+")
            for seq in ("<ButtonRelease-1>", "<B1-Motion>"):
                bar.bind(seq, self._user_scrolled, add="+")
            self.counter = 0
            self._follow = True
            self._scroll_job = None
            self._force_scroll = False
            self.configure_tags()
            self.clear()

        # ── 基本 ──
        def _key(self, event):
            if event.state & 0x4 and event.keysym.lower() in ("c", "a", "insert"):
                if event.keysym.lower() == "a":
                    self.text.tag_add("sel", "1.0", "end")
                    return "break"
                return None
            if event.keysym in ("Up", "Down", "Prior", "Next", "Home", "End"):
                return None
            return "break"

        def _copy(self, _event=None):
            try:
                text = self.text.get("sel.first", "sel.last")
            except tk.TclError:
                return "break"
            self.text.clipboard_clear()
            self.text.clipboard_append(text.replace("\u200b", ""))
            return "break"

        def _put_clipboard(self, text):
            text = (text or "").replace("\u200b", "").strip("\n")
            if text:
                self.text.clipboard_clear()
                self.text.clipboard_append(text)
                try:
                    self.app.status_label.configure(text="已複製")
                except (tk.TclError, AttributeError):
                    pass

        def message_at(self, index):
            """index 所在的那一則訊息（最上層區塊）的文字；不在任何訊息裡回傳空字串。"""
            for rid, parent in self.parent.items():
                if parent != "root":
                    continue
                try:
                    if self.text.compare(f"{rid}_s", "<=", index) and self.text.compare(index, "<", f"{rid}_e"):
                        return self.plain_text(rid)
                except tk.TclError:
                    continue
            return ""

        def _menu(self, event):
            index = self.text.index(f"@{event.x},{event.y}")
            try:
                selected = self.text.get("sel.first", "sel.last")
            except tk.TclError:
                selected = ""
            message = self.message_at(index)
            m = tk.Menu(self.text, tearoff=False)
            m.add_command(label="複製", accelerator="Ctrl+C", state="normal" if selected.strip() else "disabled",
                          command=lambda: self._put_clipboard(selected))
            m.add_command(label="複製這則訊息", state="normal" if message.strip() else "disabled",
                          command=lambda: self._put_clipboard(message))
            m.add_command(label="複製整段對話", command=lambda: self._put_clipboard(self.text.get("1.0", "end")))
            m.add_separator()
            m.add_command(label="全選", accelerator="Ctrl+A", command=lambda: self.text.tag_add("sel", "1.0", "end"))
            m.tk_popup(event.x_root, event.y_root)
            return "break"

        def plain_text(self, rid):
            return self.text.get(f"{rid}_s", f"{rid}_e").replace("\u200b", "")

        def clear(self):
            self.text.delete("1.0", "end")
            for name in list(self.text.mark_names()):
                if name not in ("insert", "current"):
                    self.text.mark_unset(name)
            self.parent, self.collapsible, self.windows, self.elided = {}, set(), [], {}
            self.on_open = {}          # 收合區塊第一次（或每次）展開時才把內容畫出來：收合的內容不放進 Text，畫面才不會越用越慢
            self.text.insert("1.0", "\n")
            self.text.mark_set("root_s", "1.0")
            self.text.mark_gravity("root_s", "left")
            self.text.mark_set("root_e", "1.0")
            self.text.mark_gravity("root_e", "right")

        def new_id(self, prefix="b"):
            self.counter += 1
            return f"{prefix}{self.counter}"

        def at_bottom(self):
            return self.text.yview()[1] >= 0.995

        def _user_scrolled(self, _e=None):
            self.text.after_idle(lambda: setattr(self, "_follow", self.at_bottom()))

        def scroll_end(self, force=False):
            """捲到最底。合併成每 80ms 最多一次：Text.see() 要重算整份版面，串流時每個字都呼叫會讓畫面卡住。"""
            if force:
                self._force_scroll = True
                self._follow = True
            if not (self._force_scroll or self._follow) or self._scroll_job:
                return
            self._scroll_job = self.text.after(80, self._do_scroll)

        def _do_scroll(self):
            self._scroll_job = None
            if self._force_scroll or self._follow:
                try:
                    self.text.see("end")
                except tk.TclError:
                    pass
            self._force_scroll = False

        def _chain(self, rid):
            tags = []
            while rid and rid != "root":
                if rid in self.collapsible:
                    tags.append(f"{rid}_body")
                rid = self.parent.get(rid)
            return tuple(tags)

        def region(self, parent="root", rid=None, prefix="b", nl_tags=()):
            """在 parent 區塊尾端建立子區塊，回傳 id。區塊後面放一個零寬字元，讓前後區塊的 mark 不會重疊。"""
            rid = rid or self.new_id(prefix)
            idx = self.text.index(f"{parent}_e")
            self.text.insert(idx, "\u200b", ("sep",) + tuple(nl_tags) + self._chain(parent))
            self.text.mark_set(f"{rid}_s", idx)
            self.text.mark_gravity(f"{rid}_s", "left")
            self.text.mark_set(f"{rid}_e", idx)
            self.text.mark_gravity(f"{rid}_e", "right")
            self.parent[rid] = parent
            return rid

        def write(self, rid, text, tags=()):
            if isinstance(tags, str):
                tags = (tags,)
            self.text.insert(f"{rid}_e", text, tuple(tags) + self._chain(rid))
            self.scroll_end()

        def clear_region(self, rid):
            self.text.delete(f"{rid}_s", f"{rid}_e")

        def set_collapsible(self, rid, collapsed):
            self.collapsible.add(rid)
            self.elided[rid] = collapsed
            self.text.tag_configure(f"{rid}_body", elide=collapsed)
            self.text.tag_raise("sep")

        def toggle(self, rid):
            self.elided[rid] = not self.elided.get(rid, False)
            self.text.tag_configure(f"{rid}_body", elide=self.elided[rid])
            return not self.elided[rid]

        def embed(self, rid, widget, pady=4):
            self.text.window_create(f"{rid}_e", window=widget, padx=0, pady=pady)
            idx = self.text.index(f"{rid}_e - 1c")
            for tag in self._chain(rid):
                self.text.tag_add(tag, idx)
            self.windows.append(widget)
            self.scroll_end()

        def _resize_windows(self):
            width = max(200, self.text.winfo_width() - 90)
            for w in list(self.windows):
                try:
                    if getattr(w, "_full_width", False):
                        w.configure(width=width)
                except tk.TclError:
                    self.windows.remove(w)

        def clickable(self, tag, callback):
            self.text.tag_bind(tag, "<Button-1>", lambda _e: callback())
            self.text.tag_bind(tag, "<Enter>", lambda _e: self.text.configure(cursor="hand2"))
            self.text.tag_bind(tag, "<Leave>", lambda _e: self.text.configure(cursor="arrow"))

        # ── 樣式 ──
        def configure_tags(self):
            t, F = self.app.theme, self.app.fonts
            w = self.text
            code_bg = mix(t["surface2"], t["text"], 0.06 if not t.dark else 0.10)
            cfg = {
                "who": dict(font=F["ui_bold"], foreground=t["muted"], spacing1=18, spacing3=4),
                "who_user": dict(font=F["ui_bold"], foreground=t["accent"], spacing1=18, spacing3=4),
                "user_text": dict(font=F["content"], foreground=t["text"], background=mix(t["accent"], t["canvas_chat"], 0.9),
                                  lmargin1=14, lmargin2=14, rmargin=60, spacing1=6, spacing3=6),
                "md_p": dict(font=F["content"], foreground=t["text"], spacing3=3),
                "md_h1": dict(font=F["h1"], foreground=t["text"], spacing1=12, spacing3=6),
                "md_h2": dict(font=F["h2"], foreground=t["text"], spacing1=10, spacing3=4),
                "md_h3": dict(font=F["h3"], foreground=t["text"], spacing1=8, spacing3=3),
                "md_bold": dict(font=F["content_bold"]),
                "md_icode": dict(font=F["mono"], background=code_bg, foreground=mix(t["accent"], t["text"], 0.35)),
                "md_code": dict(font=F["mono"], background=code_bg, foreground=t["text"], lmargin1=14, lmargin2=14,
                                rmargin=20, spacing1=0, spacing3=0),
                "md_li": dict(font=F["content"], foreground=t["text"], lmargin1=12, lmargin2=30, spacing3=2),
                "md_li2": dict(font=F["content"], foreground=t["text"], lmargin1=32, lmargin2=50, spacing3=2),
                "md_quote": dict(font=F["content"], foreground=t["muted"], lmargin1=16, lmargin2=16),
                "md_table": dict(font=F["mono"], foreground=t["text"], spacing3=0),
                "md_hr": dict(foreground=t["border"]),
                "md_link": dict(foreground=t["accent"], underline=True),
                "tool_head": dict(font=F["small"], foreground=t["muted"], background=t["surface2"], lmargin1=8,
                                  lmargin2=8, spacing1=3, spacing3=3),
                "tool_ok": dict(foreground=t["success"]),
                "tool_bad": dict(foreground=t["danger"]),
                "tool_run": dict(foreground=t["accent"]),
                "tool_out": dict(font=F["mono_small"], foreground=t["muted"], background=t["surface2"], lmargin1=26,
                                 lmargin2=26, rmargin=20, spacing1=0, spacing3=0),
                "card_title": dict(font=F["ui_bold"], foreground=t["text"], background=mix(t["warning"], t["canvas_chat"], 0.86),
                                   lmargin1=12, lmargin2=12, spacing1=8, spacing3=4),
                "card_body": dict(font=F["mono_small"], foreground=t["text"], background=mix(t["warning"], t["canvas_chat"], 0.92),
                                  lmargin1=12, lmargin2=12, rmargin=20, spacing1=0, spacing3=0),
                "card_done": dict(font=F["small"], foreground=t["muted"], lmargin1=12, spacing1=2, spacing3=6),
                "notice": dict(font=F["small"], foreground=t["muted"], lmargin1=0, spacing1=6, spacing3=6),
                "error": dict(font=F["ui"], foreground=t["danger"], spacing1=6, spacing3=6),
                "sec_head": dict(font=F["ui_bold"], foreground=t["text"], background=t["surface2"], lmargin1=8,
                                 lmargin2=8, spacing1=6, spacing3=6),
                "sec_meta": dict(font=F["small"], foreground=t["muted"]),
                "model_head": dict(font=F["ui_bold"], foreground=t["text"], lmargin1=14, spacing1=8, spacing3=2),
                "final_head": dict(font=F["h2"], foreground=t["accent"], spacing1=14, spacing3=6),
                "progress": dict(font=F["small"], foreground=t["muted"], spacing1=2, spacing3=2),
                "empty_title": dict(font=F["h1"], foreground=t["text"], justify="center", spacing1=60, spacing3=8),
                "empty_body": dict(font=F["content"], foreground=t["muted"], justify="center", spacing3=4),
            }
            for name, opts in cfg.items():
                w.tag_configure(name, **opts)
            w.tag_configure("sep", elide=True)          # 區塊之間的分隔字元：不顯示、不佔空間
            for name in ("md_bold", "md_icode", "md_link", "tool_ok", "tool_bad", "tool_run", "sec_meta"):
                w.tag_raise(name)
            # v6.6.3：選取的顏色要蓋過訊息底色。以前「你」的訊息、程式碼、工具輸出都有底色，選取時看不出反白，像是不能選。
            w.tag_raise("sel")

        # ── Markdown ──
        def render_markdown(self, rid, md, extra=()):
            in_code = False
            lines = (md or "").replace("\r\n", "\n").strip("\n").split("\n")
            for line in lines:
                stripped = line.strip()
                if stripped.startswith("```"):
                    in_code = not in_code
                    continue
                if in_code:
                    self.write(rid, line + "\n", ("md_code",) + extra)
                    continue
                m = re.match(r"(#{1,6})\s+(.*)", stripped)
                if m:
                    level = len(m.group(1))
                    self._inline(rid, m.group(2), ("md_h1" if level == 1 else "md_h2" if level == 2 else "md_h3",) + extra)
                elif re.match(r"^\s*([-*_])\s*\1\s*\1[\s\1]*$", line):
                    self.write(rid, "─" * 40, ("md_hr",) + extra)
                elif re.match(r"[-*+]\s+", stripped):
                    indent = len(line) - len(line.lstrip())
                    tag = "md_li2" if indent >= 2 else "md_li"
                    self.write(rid, "•  ", (tag,) + extra)
                    self._inline(rid, re.sub(r"^[-*+]\s+", "", stripped), (tag,) + extra)
                elif re.match(r"\d+[.)]\s+", stripped):
                    indent = len(line) - len(line.lstrip())
                    tag = "md_li2" if indent >= 2 else "md_li"
                    num = re.match(r"(\d+[.)])\s+", stripped)
                    self.write(rid, num.group(1) + " ", (tag,) + extra)
                    self._inline(rid, stripped[num.end():], (tag,) + extra)
                elif stripped.startswith(">"):
                    self._inline(rid, "▍ " + stripped.lstrip("> "), ("md_quote",) + extra)
                elif stripped.startswith("|") and stripped.endswith("|"):
                    if re.fullmatch(r"\|?[\s:|-]+\|?", stripped):
                        continue
                    cells = [c.strip() for c in stripped.strip("|").split("|")]
                    self.write(rid, "  " + "  │  ".join(cells), ("md_table",) + extra)
                else:
                    self._inline(rid, line, ("md_p",) + extra)
                self.write(rid, "\n", ("md_p",) + extra)

        def _inline(self, rid, text, tags):
            pos = 0
            for m in INLINE_MD.finditer(text):
                if m.start() > pos:
                    self.write(rid, text[pos:m.start()], tags)
                token = m.group(0)
                if token.startswith("**"):
                    self.write(rid, token[2:-2], tags + ("md_bold",))
                elif token.startswith("`"):
                    self.write(rid, token[1:-1], tags + ("md_icode",))
                else:
                    label = re.match(r"\[([^\]]+)\]", token).group(1)
                    self.write(rid, label, tags + ("md_link",))
                pos = m.end()
            if pos < len(text):
                self.write(rid, text[pos:], tags)

        # ── 高階元件 ──
        def empty_state(self, title, lines):
            rid = self.region()
            self.write(rid, title + "\n", "empty_title")
            for line in lines:
                self.write(rid, line + "\n", "empty_body")
            return rid

        def user_message(self, text):
            rid = self.region()
            self.write(rid, "你\n", "who_user")
            self.write(rid, text.strip() + "\n", "user_text")
            self.scroll_end(force=True)
            return rid

        def assistant_message(self, who):
            rid = self.region()
            self._follow = True
            self.write(rid, who + "\n", "who")
            body = self.region(rid)
            return body

        def finish_markdown(self, body, md):
            self.clear_region(body)
            if md.strip():
                self.render_markdown(body, md)

        def notice(self, text, kind="notice"):
            rid = self.region()
            self.write(rid, text + "\n", kind)
            return rid

        def tool_card(self, title, icon="•"):
            rid = self.region(prefix="t")
            self._follow = True
            head = self.region(rid)
            body = self.region(rid)
            self.set_collapsible(body, True)
            tag = f"{head}_click"
            self.write(head, f"  ▸ {icon}  ", ("tool_head", tag))
            self.write(head, title, ("tool_head", tag))
            status = self.region(head, nl_tags=("tool_head", tag))
            self.write(head, "\n", ("tool_head", tag))
            self.clickable(tag, lambda: self._toggle_tool(head, body))
            return {"rid": rid, "head": head, "status": status, "body": body, "tag": tag}

        def _toggle_tool(self, head, body):
            if self.elided.get(body, False) and body in self.on_open:
                try:
                    self.on_open[body]()
                except Exception:
                    log_app.exception("展開區塊失敗")
            opened = self.toggle(body)
            ranges = self.text.tag_ranges(f"{head}_click")
            if ranges:
                start = ranges[0]
                arrow_idx = self.text.search("▸" if opened else "▾", start, f"{start} lineend")
                if arrow_idx:
                    self.text.delete(arrow_idx)
                    self.text.insert(arrow_idx, "▾" if opened else "▸", ("tool_head", f"{head}_click"))

        def set_tool_status(self, card, text, kind="tool_run"):
            self.clear_region(card["status"])
            self.write(card["status"], "   " + text, ("tool_head", kind, card["tag"]))

        def tool_output(self, card, text):
            body = card["body"]

            def fill():
                self.on_open.pop(body, None)
                self.clear_region(body)
                self.write(body, (text or "（沒有輸出）").rstrip() + "\n", "tool_out")

            if self.elided.get(body, False):
                self.clear_region(body)
                self.on_open[body] = fill
            else:
                fill()


    class AIWorkbench(tk.Tk):
        def __init__(self):
            super().__init__()
            self.withdraw()
            self.report_callback_exception = self._report_exception
            self.scale = max(1.0, min(2.5, self.winfo_fpixels("1i") / 96.0))
            self.title(f"{APP_NAME} {APP_VERSION}")
            try:                                   # 專屬圖示（原創 Q 版主持 AI 頭像）
                self._icons = [tk.PhotoImage(data=APP_ICON_PNG[n]) for n in (64, 32, 16)]
                self.iconphoto(True, *self._icons)
            except Exception:
                log_app.warning("設定視窗圖示失敗", exc_info=True)
            self.ui_state = load_ui_state()
            sw, sh = self.winfo_screenwidth(), self.winfo_screenheight()
            w, h = min(int(1440 * self.scale), int(sw * 0.94)), min(int(900 * self.scale), int(sh * 0.9))
            geometry = self.ui_state.get("geometry") or ""
            m = re.fullmatch(r"(\d+)x(\d+)\+(-?\d+)\+(-?\d+)", geometry)
            if m and int(m.group(1)) <= sw + 50 and int(m.group(2)) <= sh + 50 \
                    and -100 < int(m.group(3)) < sw - 100 and -50 < int(m.group(4)) < sh - 100:
                self.geometry(geometry)
            else:
                self.geometry(f"{w}x{h}+{max(0, (sw - w) // 2)}+{max(0, (sh - h) // 3)}")
            self.minsize(int(900 * min(self.scale, sw / 1200)), int(560 * min(self.scale, sh / 760)))

            imported = ""
            if FROZEN:
                src = find_importable_settings()
                if src and messagebox.askyesno(APP_NAME, f"這是打包版第一次在這個資料夾啟動。\n\n"
                                               f"發現既有設定：\n{src}\n\n要沿用它（AI 團隊、偏好）嗎？"
                                               "\n（金鑰本體不會被複製，仍從環境變數讀取。）"):
                    if import_settings_from(src):
                        imported = src
            settings, warning = load_settings_file()
            self._imported_settings = imported
            self._settings_digest = settings_file_digest()     # 用來發現「另一個程式改過設定檔」
            self.instance_owner = True                         # main() 會依單一執行鎖改寫
            self.settings = settings
            self.services = settings["services"]
            fix_service_names(self.services)
            for s in self.services:
                s.setdefault("credential", s.get("credential_env", ""))
                if not s["credential"] and NVIDIA_HOST in s.get("url", "").lower():
                    s["credential"] = DEFAULT_NVIDIA_ENV
            self.prefs = settings["preferences"]
            self._apply_advanced_prefs()
            self.theme = Theme(self.prefs)
            self._tk_widgets = []
            self.model_cache = {}
            self.mcp = MCPManager()
            self._unattended = None           # 正在執行的排程（沒有人在旁邊核准）
            self._sched_running = None
            self._launched_schedule = None
            self.ui_queue = queue.Queue()
            self.active, self.active_lock = {}, threading.Lock()
            self.key_hints = {}
            self.editors = {}
            self.dirty = False
            self._graph_job = None
            self.busy = False
            self.token = None
            # Agent
            self.runner = None
            self.runner_key = None
            self.agent_body = None
            self.agent_buffer = []
            self.agent_text = ""
            self.tool_cards = {}
            self.cat_last_card = {}
            self.current_tool = None
            self.pending_cards = []
            self.agent_step = 0
            self.agent_usage = {}
            # AI 討論
            self.session = None              # 進行中的討論（Session 物件）
            self.cancel_event = None
            self.run = {}
            self.buffers = {}
            self.council_ui = None
            self.last_record = None
            self.last_record_path = ""
            self.expected = self.done_calls = 0
            self.usage = {}
            self.phase_text = ""
            self.run_started = 0.0
            self.call_started = {}

            self._init_fonts()
            self._style()
            self._build()
            self._refresh_templates()
            self._rebuild_editors()
            self._refresh_hub_choices()
            self._refresh_model_choices()
            self._apply_theme()
            self.refresh_sessions()
            self.new_conversation(self.prefs.get("new_chat_type", "agent"))
            self.protocol("WM_DELETE_WINDOW", self._on_close)
            for seq in ("<MouseWheel>", "<Button-4>", "<Button-5>"):
                self.bind_all(seq, self._on_mousewheel, add="+")
            self.bind("<Control-s>", lambda _e: self.save_settings())
            self.bind("<Control-n>", lambda _e: self.new_conversation())
            self.bind("<Control-e>", lambda _e: self.export_conversation())
            self.bind("<Escape>", lambda _e: self.stop())
            self.bind("<F11>", lambda _e: self.toggle_panel())
            self.after(40, self._process_queue)
            self.after(300, self._install_file_drop)
            self.after(1000, self._tick)
            self.after(800, self.start_mcp)
            self._start_monitor()
            self.rd = None                      # 自主研發的狀態（沒有在跑時是 None）
            self.after(1500, self._report_interrupted)
            self.after(3000, self._check_schedule_paths)
            self.after(2000, self._report_previous_crash)
            self.after(10000, self._auto_update_check)
            self.after(6000, self._daily_health_check)
            self.deiconify()
            if self.ui_state.get("zoomed"):
                try:
                    self.state("zoomed")
                except tk.TclError:
                    pass
            if warning:
                self.after(300, lambda: messagebox.showwarning(APP_NAME, warning))

        # ───────────── 字體與主題 ─────────────
        def _font_sizes(self):
            size = int(self.prefs.get("font_size") or 10)
            rsize = int(self.prefs.get("reply_font_size") or 11)
            return {"ui": size - 1, "ui_bold": size - 1, "small": max(7, size - 2), "section": size,
                    "title": size + 3, "button": size - 1, "primary": size, "content": rsize, "content_bold": rsize,
                    "h1": rsize + 5, "h2": rsize + 3, "h3": rsize + 1, "mono": max(8, rsize - 1),
                    "mono_small": max(7, rsize - 2), "side": size - 1}

        def _init_fonts(self):
            self.fonts = {}
            for key in self._font_sizes():
                self.fonts[key] = tkfont.Font(self)
            self._update_fonts()

        def _update_fonts(self):
            fam = self.prefs.get("font_family") or DEFAULT_UI_FONT
            cfam = self.prefs.get("content_family") or fam
            bold = {"ui_bold", "section", "title", "primary", "content_bold", "h1", "h2", "h3"}
            for key, size in self._font_sizes().items():
                family = DEFAULT_MONO_FONT if key.startswith("mono") else (
                    cfam if key in ("content", "content_bold", "h1", "h2", "h3") else fam)
                self.fonts[key].configure(family=family, size=size, weight="bold" if key in bold else "normal")

